COLLDATA("sh4151","ar",[[1,"كتاب الكبائر"],[2,"للحافظ أبي بكر أحمد بن هارون البرديجي"],[3,"تحقيق"],[4,"د. محمد بن تركي التركي"],[5,"الأستاذ المساعد في كلية التربية في جامعة الملك سعود"],[6,"ال"],[7,"مقدمة"],[8,"إن الحمد لله، نحمده ونستعينه، ونستغفره، ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مُضل له، ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله."],[9,"﴿يَا أَيُّهَا الذِينَ آمَنُوا اتقُوا اللهَ ّحقَ تُقَاتِهِ وَلاَ تَمُوتُنَّ إِلاَ وَأَنتُمْ مُسْلِمُون﴾ ."],[10,"﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ الذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللهَ الذِي تَسَآلُونَ بِهِ وَالأَرْحَام إِنَّ اللهَ كَانَ عَلَيكم رَقِيبًَا﴾ ."],[11,"﴿يَا أَيُّهَا الذِينَ آمَنُوا اتَّقُوا اللهَ وَقُولُوا قَوْلًا سَدِيدًَا يَصْلِحْ لَكُم أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِع اللهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًَا عَظِيمًَا﴾ ."],[12,"أما بعد، فهذا كتاب صغير في حجمه، كبير في مادته وموضوعه، ولإمام من الأئمة الحفاظ المغمورين، أحببت التعليق عليه، وخدمته بما يليق به."],[13,"ودفعني إلى اختياره عدة أمور، من أهمها كونه أول كتاب يُصنف في الكبائر، بل يكاد يكون الكتاب الوحيد من الكتب المتقدمة التي وصلتنا في هذا الموضوع، إذ لم أقف على شيء مما ألف في بيان الكبائر قبل كتاب الذهبي سوى هذا الكتاب."],[14,"إضافة إلى أنه لإمام من الأئمة الحفاظ الذين لم يصلنا من مصنفاته إلا كتابين فقط، طبع أحدهما١، وهذا هو الآخر، أحببت أن أقوم بتحقيقه وإخراجه إلى عالم المطبوعات، على الوجه اللائق به ولهذا وغيره قمت بتحقيقه ودراسته بما تقتضيه قواعد التحقيق، من غير تطويل ممل ولا إيجاز مخل، محاولًا قدر الإمكان التركيز على الجانب الحديثي في تعليقي على الكتاب."],[15,"ولذا فلم أر أن أترجم لرجال الإسناد كلهم، وإنما أقتصر على بيان حال من عليهم مدار الحديث، ممن يكون في بيان حالهم دور في تصحيح الحديث أو تضعيفه."],[16,"ولكني توسعت في تخريج الأحاديث، لأن هذا في نظري أهم من الإطالة في التراجم، وخاصة أن أكثر هذه الأحاديث جاء في أسانيدها بعض العلل، فكان لابد من التوسع في ذلك، لبيان الأوجه الراجحة من المرجوحة."],[17,"وقد قدمت للكتاب بمقدمة قصيرة، ذكرت فيها نبذة موجزة عن الكبائر، ثم ترجمة موجزة للمؤلف، ثم دراسة للكتاب، كما سيأتي."],[18,"وأخيرًا هذا هو جهد المُقِل، ولا ينفك عن كونه عمل بشر، وعمل البشر مهما كان لا يخلو من النقص والخلل، وعذري أني بذلت جهدي واستطاعتي فيه، فما كان من صواب فبتوفيق من الله وحده، وما كان فيه من خلل ونقص فمني ومن الشيطان، وأسأل الله بمنه وكرمه أن يتجاوز ذلك كله عني."],[19,"كما أسأله - عز وجل - أن يجعل عملي هذا خالصًا لوجهه الكريم، وأن ينفعني به، يوم لا ينفع مال ولا بنون."],[20,"وآخر دعوانا أن الحمد لله رب العالمين"],[21,"وصلى الله وسلم على نبينا محمد، وعلى آله وصحبه أجمعين."],[22,"نبذة عن الكبائر، تعريف الكبيرة"],[23,"..."],[24,"نبذة موجزة عن الكبائر"],[25,"تعريف الكبيرة:"],[26,"اختلف العلماء في تعريف حد الكبيرة على أقوال كثيرة جدًا ليس هنا موضع ذكرها وبيان اختلاف العلماء فيها١."],[27,"ومن أشهر ما قيل في تعريف الكبيرة:"],[28,"قيل: إن الكبيرة هي ما عليه حدٌّ في الشرع."],[29,"وقيل: إنها المعصية التي يلحق صاحبها الوعيد الشديد بنص كتاب أو سنة."],[30,"وقيل: إنها كل ذنب رُتب عليه حدٌّ في الدنيا، أو وعيد شديد في الآخرة."],[31,"وقيل: كل ما نهى الله عنه فهو كبيرة."],[32,"وقيل: هي كل ذنب خُتم بلعنة، أو غضب، أو نار."],[33,"وقد رجح هذا التعريف الأخير شيخ الإسلام ابن تيمية، وبين سلامة هذا التعريف من القوادح الواردة على غيره، وتكلم بكلام نفيس في هذا الجانب، فليراجع."],[34,"وقال الحافظ ابن حجر بعد استعراضه لعدد من الأقوال، قال: ومن أحسن التعاريف قول القرطبي في المفهم: \"كل ذنب أطلق عليه بنص كتاب أو سنة أو إجماع أنه كبيرة أو عظيم، أو أخبر فيه بشدة العقاب، أو علق عليه الحد، أو شدد النكير عليه فهو كبيرة\"."],[35,"قال الحافظ: وعلى هذا فينبغي تتبع ما ورد فيه الوعيد أو اللعن أو الفسق، من القرآن، أو الأحاديث الصحيحة والحسنة، ويُضم إلى ما ورد فيه التنصيص في القرآن والأحاديث الصحاح والحسان على أنه كبيرة، فمهما بلغ مجموع ذلك عُرف منه تحرير عدّها."],[36,"وتبعًا للاختلاف السابق في تعريف الكبيرة اختلف العلماء أيضًا في تحديد عدد الكبائر، وما هي، فمن اقتصر على أنها ما جاء النص على أنه كبيرة قال إنها سبع، أو تسع، كما جاء ذلك في الأحاديث الواردة في الكبائر ومن عرّفها بتعريف أوسع قال إنها أكثر من ذلك، وهكذا."],[37,"ولمعرفة الأقوال في ذلك راجع المصادر المتقدمة في تعريف الكبيرة."],[38,"المؤلفات في الكبائر"],[39,"رغم أهمية هذا الموضوع وخطره، فلم أقف إلا على عدد قليل من الكتب ممن أفرد هذه الكبائر بكتاب مستقل، إلا أن الكثير من العلماء قد ضمنوها كتبهم، فتجد ذكر الكبائر ضمن كتب الحديث، والعقيدة، وغيرها."],[40,"ومما وقفت عليه ممن أفرد الكبائر بتأليف مستقل ما يلي:"],[41,"١- كتاب الكبائر، للبرديجي."],[42,"وسيأتي الكلام عليه مفصلًا."],[43,"٢- كتاب الكبائر للذهبي."],[44,"وهو كتاب معروف ومشهور، وقد طبع عدة مرات."],[45,"٣- الكبائر، للعلائي."],[46,"ذكره ابن حجر الهيثمي في الزواجر ١/١٤، فقال: وقال شيخ الإسلام العلائي في قواعده١:إنه صنف جزءًا جمع ما فيه نص صلى الله عليه وآله وسلم فيه على أنه كبيرة."],[47,"ثم ذكر العلائي عددًا من الكبائر، وقال: فهذه الخمسة والعشرون هي مجموع ما جاء في الأحاديث منصوصًا عليه أنه كبيرة."],[48,"٤- الكبائر للديلمي."],[49,"ذكره ابن حجر الهيثمي في الزواجر ١/١٤، فقال: قال الديلمي من أصحابنا: وقد ذكرنا عددها في تأليف لنا باجتهادنا، فزادت على أربعين كبيرة."],[50,"٥- كتاب الزواجر عن اقتراف الكبائر، لابن حجر الهيثمي."],[51,"وهو أيضًا مطبوع عدة مرات، ولعله من أوسع الكتب المؤلفة في هذا الموضوع."],[52,"٦- كتاب الكبائر، للشيخ محمد بن عبد الوهاب."],[53,"وهو كتاب مشهور، وقد طبع عدة طبعات أيضًا."],[54,"٧- العمدة بتمييز الكبائر، لأحمد الشريف البرقاوي."],[55,"وهو مطبوع، وصدر عن دار الأرقم بالكويت، عام ١٤٠٥؟."],[56,"٨- الكبيرة والمذاهب فيه، تأليف حاسي كوتا."],[57,"وهو رسالة ماجستير، بجامعة أم القرى، كلية الشريعة، عام ١٤٠١؟."],[58,"هذا بعض ما وقفت عليه من الكتب المفردة في موضوع الكبائر، إلا أنه كما قدمت قد تكلم عنه عدد من الأئمة في ثنايا كتبهم."],[59,"ومن أوسع ما وجدته ما يلي:"],[60,"الإمام ابن منده في كتابه الإيمان ٢/٥٤٤، وما بعدها."],[61,"والإمام اللالكائي في كتابه شرح اعتقاد أصول أهل السنة ٦/١١٠٣، وما بعدها."],[62,"والإمام ابن القيم في إعلام الموقعين ٤/٤٠١. وقد اقتصر على تعداد الكبائر فقط."],[63,"وكذا تكلم عنها في الجواب الكافي ص١٨٦، وما بعدها."],[64,"والإمام ابن النحاس في كتابه تنبيه الغافلين ص١١٩، وما بعدها."],[65,"وقد ذكر أنه استدرك كثيرًا من الكبائر مما أغفله الذهبي وابن القيم."],[66,"وانظر أيضًا المراجع المتقدمة في تعريف الكبيرة."],[67,"ترجمة المؤلف"],[68,"..."],[69,"ترجمة موجزة للمؤلف١٢"],[70,"اسمه ونسبه ومولده:"],[71,"هو: الحافظ أبو بكر أحمد بن هارون بن رَوح البَرْدِيجي٣، البَرْذَعي٤، النيسابوري، نزيل بغداد."],[72,"ولد بعد الثلاثين ومائتين، أو قبلها."],[73,"شيوخه:"],[74,"سمع الحافظ البرديجي من الكثير من الشيوخ، ولا عجب في ذلك، فهو قد رحل إلى بلدان كثيرة، ومن الطبيعي كثرة شيوخه مع تعدد رحلاته."],[75,"وقد ذكر له مترجموه عددًا من الشيوخ، وسأكتفي بذكر بعضهم مراعاة للاختصار، ولأن استيعابهم مما ليس من مقصدنا هنا."],[76,"فمن أشهر شيوخه:"],[77,"أبو زرعة عبيد الله بن عبد الكريم الرازي، محمد بن إسحاق الصَّغاني، محمد بن عبد الملك الدَّقيقي، محمد بن يحيى الذهلي، نصر بن علي الجَهْضَمي، هارون بن إسحاق الهمداني، أبو سعيد الأشج، وغيرهم."],[78,"تلاميذه"],[79,"كما ذكر له مترجموه عددًا من التلاميذ، فمن أشهرهم:"],[80,"أبو عمرو أحمد بن المبارك المُسْتَملي، جعفر بن أحمد بن سنان القطان، أبو القاسم سليمان بن أحمد الطبراني، أبو أحمد عبد الله بن عدي الجرجاني، عبد الله بن محمد بن عمران المعدل، علي بن محمد بن لؤلؤ الوراق، وغيرهم."],[81,"طلبه للعلم ورحلاته"],[82,"العلمية:"],[83,"كان الإمام البرديجي - رحمه الله - حريصًا على طلب العلم، جادًا في تحصيله، ولا أدل على ذلك من أنه قد رحل في طلب العلم في سن مبكرة."],[84,"يدلّ على ذلك ما أورده الحاكم في تاريخه قال: قرأت بخط أبي علي المُستملي سماعه من أحمد بن هارون البردعي الحافظ في مسجد محمد بن يحيى - يعني الذهلي - في صفر، سنة خمس وخمسين ومائتين١."],[85,"وتقدم أنه قد ولد حوالي سنة ثلاثين ومائتين."],[86,"ويدل على حرصه أيضًا كثرة البلدان التي سمع فيها."],[87,"قال الذهبي بعد أن ذكر معظم شيوخه: وطبقتهم بالشام، والحرمين، والعَجَم، ومصر، والعراق، والجزيرة٢."],[88,"وقال ابن العديم: وهو حافظ معروف رحل وطاف٣."],[89,"وهذا ما جعل البرديجي يبلغ مكانة عالية، ويحرص العلماء على السماع والاستفادة منه، سواء كانوا من شيوخه أو تلامذته."],[90,"قال الحاكم في تاريخه: ورد نيسابور على محمد بن يحيى الذهلي، فاستفاد وأفاد، وكتب عنه مشايخنا في ذلك العصر، ولا أعرف إمامًا من أئمة عصره في الآفاق إلا وله عليه انتخاب يُستفاد١."],[91,"وقد أورد الحافظ ابن عساكر٢عددًا من شيوخه الذين سمع منهم، وذكر البلدان التي سمع فيها منهم، فمن هذه البلدان: بيروت، ودمشق، وحمص، ومصر، وحَرَّان، والمِصَّيصة، والكوفة، وبغداد، ومكة."],[92,"توثيقه، وثناء العلماء عليه:"],[93,"أجمع كل من ترجم له على إمامته وتوثيقه وحفظه٣."],[94,"قال الدارقطني: ثقة مأمون جبل."],[95,"وقال أبو الشيخ الأصبهاني: من حفاظ الحديث وكبرائهم."],[96,"وقال الخطيب: كان ثقة فاضلًا فَهمًا حافظًا."],[97,"قال الذهبي: الإمام الحافظ الحجة... جمع وصنف، وبرع في علم الأثر."],[98,"وبنحو ذلك وصفه غير واحد من الأئمة، مما يطول استقصاؤه."],[99,"توثيقه وثناء العلماء عليه"],[100,"مؤلفاته"],[101,"..."],[102,"مؤلفاته:"],[103,"ذكر غير واحد ممن ترجم له أنه له عدة مصنفات."],[104,"وقد تتبعت مؤلفاته في بحثي الموسع عن ترجمته، ونقولات العلماء عن هذه المؤلفات، وما وصلنا منها، وسأكتفي هنا بذكر أسماء هذه المؤلفات فقط:"],[105,"١- كتاب الكبائر، وسيأتي الكلام عليه."],[106,"٢- كتاب طبقات الأسماء المفردة من الصحابة والتابعين وأصحاب الحديث، وهو مطبوع."],[107,"٣- كتاب معرفة المتصل من الحديث، والمرسل والمقطوع، وبيان الطريق الصحيحة."],[108,"٤- كتاب المراسيل."],[109,"٥- كتاب الفوائد."],[110,"٦- كتاب في الجرح والتعديل."],[111,"ولم أقف على اسمه، ولكن وجدت منه نقولات عدة في جرح الرجال وتعديلهم عند الخطيب البغدادي، وابن عدي، والحافظ ابن حجر، وغيرهم."],[112,"وفاته"],[113,"اتفقت مصادر ترجمته على أنه توفي سنة إحدى وثلاث مائة، ببغداد١."],[114,"قال أبو الشيخ الأصبهاني: مات سنة إحدى وثلاث مائة ببغداد."],[115,"وقال أحمد بن كامل: مات في شهر رمضان سنة إحدى وثلاثمائة ببغداد."],[116,"وكذا قال أكثر من ترجم له."],[117,"التعريف بالكتاب"],[118,"اسم الكتاب:"],[119,"جاء اسم الكتاب في النسخة المخطوطة: \"جُزْءٌ فِيهِ مَنْ رَوَى عَنِ النَّبِيِّ صلى الله عليه وآله وسلم مِنَ الصَّحَابَةِ فِي الْكَبَائِرِ\"، وجاء في السماعات الملحقة بالكتاب باسم: \"ما روي في الكبائر\"."],[120,"توثيق نسبته إلى مؤلفه:"],[121,"لم أقف على من ذكر أن للبرديجي كتابًا في الكبائر، إلا أن هذا لا يعني التشكيك في صحة نسبته إليه، بل يمكن الجزم بأنه من تأليفه لعدة أمور:"],[122,"١- وجود الإسناد المتصل إلى مؤلفه، وأنه من تأليفه."],[123,"٢- جود السماعات الكثيرة التي على الكتاب، والتي تثبت أنه من تأليفه، ومن بينها سماعات لعدد من الحفاظ كالضياء المقدسي، وابن عبد الهادي، وغيرهم."],[124,"٣- إن الشيوخ المذكورين في بداية كل حديث هم من شيوخ المصنف."],[125,"٤- وجود بعض الأحاديث قد رويت من طريق المصنف بنفس الإسناد الوارد عنده في هذا الكتاب، كما سيأتي في تخريج الأحاديث، مما يدل على اعتماد من أخرج الحديث من طريقه على كتابه هذا."],[126,"كما إن الحافظ ابن حجر نقل روايات عن البرديجي، كماسيأتي، موجودة في كتابه هذا، مما يدل على استفادته منه، وإن كان لم يصرح باسم كتابه."],[127,"ولهذا فالراجح أنه من تأليفه، وأما عدم اشتهاره، وذكره عند العلماء فلعل ذلك بسبب كونه صغير الحجم، إذ إن عدد الأحاديث الواردة فيه أحد عشر حديثًا فقط."],[128,"موضوعه وأهميته"],[129,"..."],[130,"موضوع الكتاب:"],[131,"يكاد عنوان الكتاب ينبئ عن مضمونه وموضوعه، فهو كتاب خاص بذكر الأحاديث الواردة في الكبائر وما ورد في التشديد فيها."],[132,"وإن كان لم يستوعب جميع هذه الأحاديث، فقد فاته الكثير، كما سيأتي."],[133,"أهمية الكتاب:"],[134,"يحتل كتابنا هذا أهمية خاصة، وذلك لعدة أمور:"],[135,"١- أنه يعتبر أول كتاب أفرده مؤلفه لذكر الكبائر، فلم أقف بعد طول بحث على من ألف في الكبائر قبله."],[136,"٢- أنه يعتبر الكتاب الوحيد في بابه خلال القرون المتقدمة، فلم أقف أيضًا على من ألف في الكبائر بعده إلا الإمام الذهبي، وبينهما أكثر من أربعمائة سنة."],[137,"٣- أنه يمتاز بأن مؤلفه يسوق الأحاديث فيه بإسناده، شأنه شأن العلماء في عصره، وهذا مما يعطي الكتاب أهمية أخرى."],[138,"٤- أن مؤلفه إمام حافظ متفق على إمامته وتوثيقه، كما تقدم."],[139,"٥- أنه انفرد بطرقٍ لبعض الأحاديث، لم أجدها عند غيره، كما في حديث أبي هريرة، وحديث أبي أيوب."],[140,"٦- أنه في موضوع مهم جدًا لكل مسلم، ولابد له من الإحاطة به."],[141,"بالإضافة إلى عدة أمور أخرى ستأتي في منهج المؤلف."],[142,"منهج المؤلف فيه"],[143,"..."],[144,"منهج المؤلف في الكتاب:"],[145,"من خلال نظرة بسيطة على الكتاب، يمكن أن نوجز منهج المؤلف في كتابه في النقاط التالية:"],[146,"١- أنه اقتصر فيه على ما ورد النص صراحة بأنه من الكبائر، ولم يذكر الأحاديث الأخرى التي يمكن أن تندرج تحت الكبائر، مما ليس فيه النص بأنه كبيرة."],[147,"٢- أنه اقتصر في كل حديث على طريق واحد عن كل صحابي، فتراه يذكر الصحابي، ثم يورد عنه طريقًا واحدًا، ولعله أراد الاختصار في ذلك، بدليل أننا نجده أحيانًا يذكر أنه روي عن هذا الصحابي من أكثر من طريق، ويقتصر على أحدها، فيقول مثلًا: وَعَبْدُ اللَّهِ بْنُ عَمْرٍو، مِنْ طرقٍ أَصَحُّهَا، ثم يورد الطريق إليه."],[148,"وهذا يعني أن عنده طرقًا أخرى، ولكنه أراد الاختصار على رواية واحدة."],[149,"٣- أنه يعتني بالتفريق بين ألفاظ الرواة، فتراه مثلًا في الحديث الأول يفرق بين لفظ ابن نمير للحديث، ولفظ الثوري وجرير."],[150,"٤- اهتمامه بمتون الأحاديث، وما فيها من زيادات، فتراه مثلًا في الحديث رقم ٥ يقول بعده: وَلَيْسَ فِي كُلِّ الْحَدِيثِ: \"ذِكْرُ قَذْفِ الْمُحْصَنَاتِ\"."],[151,"٥- عنايته بتعليل الأحاديث، فتراه في الحديث التاسع يفرق بين من رواه مرفوعًا، ومن رواه موقوفًا."],[152,"٦- ومن منهجه أيضًا العناية بالأسماء والألقاب، ففي الحديث التاسع قال: وَهُوَ طَيْسَلَةُ بْنُ ميَّاس، وَمَياسٌ لَقَبٌ، وَهُوَ طيسلة بن علي الحنفي."],[153,"الملاحظات على الكتاب:"],[154,"ليس هناك من ملاحظات تذكر على الكتاب، إلا عدم شموله للأحاديث الواردة في الكبائر."],[155,"ويمكن الجواب على هذا بأن يقال: إن هذه الأحاديث هي التي وقعت للمؤلف بإسناده، ويدل على ذلك قول المؤلف في بداية الكتاب: \"رَوَى أَحَدَ عَشَرَ رَجُلا مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وآله وسلم في الكبائر \". فهذا دليل على أنه لم يقع له غير أحاديثهم، وإلا لذكرها."],[156,"ومن الملاحظات أيضًا سياقه لبعض الأحاديث التي في أسانيدها ضعفاء، وعدم التنبيه على ذلك."],[157,"وهذا يمكن الجواب عليه بأن سياقه للإسناد كاف في ذلك، وهذا منهج معروف عند الكثير من العلماء."],[158,"وصف النسخ الخطية"],[159,"..."],[160,"وصف النسخة الخطية:"],[161,"اعتمدت في تحقيق هذا الكتاب على النسخة الوحيدة له - حسب علمي - وهي من محفوظات المكتبة الظاهرية، ضمن المجموع رقم ٨١، من الورقة ١ إلى الورقة ٥."],[162,"وهي من رواية الضياء المقدسي، وقد روى معها أيضًا إملاءان من أمالي أبي سعيد محمد بن أحمد بن جعفر بن ملة."],[163,"كما أن الحافظ الضياء المقدسي قد استدرك بعض الأحاديث على البرديجي، وساق أكثرها بإسناده١."],[164,"وهذه النسخة مكتوبة بخط واضح، وقد استدرك الناسخ في الهامش بعض الأخطاء والسقط، إلا أنه في مواضع قليلة قد فاته بعض الشيء، كما سيأتي."],[165,"وهذه النسخة عليها الكثير من السماعات، وسيأتي ذكر بعضها."],[166,"تراجم رواة الكتاب"],[167,"وصل إلينا هذا الكتاب من رواية الضياء المقدسي أبي عبد الله محمد بن عبد الواحد، عن أبي القاسم عبد الواحد بن القاسم، عن أبي علي الحسن بن أحمد الحداد، عن أبي نعيم الأصبهاني، عن أبي علي الصواف، عن مؤلفه."],[168,"وفيما يلي تراجم موجزة لهؤلاء الرواة:"],[169,"١- الضياء المقدسي:"],[170,"هو أبو عبد الله محمد بن عبد الواحد بن أحمد بن عبد الرحمن المقدسي."],[171,"ولد سنة تسع وستين وخمسمائة."],[172,"وهو ثقة حافظ متقن، أثنى عليه كل من ترجم له١."],[173,"وأخباره، وثناء العلماء عليه كثير جدًا، ليس هنا مجال التفصيل في ذلك."],[174,"قال ابن النجار: هوحافظ متقن، ثبت ثقةصدوق، نبيل حجة، عالم بالحديث وأحوال الرجال، له مجموعات وتخريجات، وهو ورع تقي زاهد عابد، محتاط في أكل الحلال، مجاهد في سبيل الله، ولعمري ما رأيت مثله في نزاهته وعفته، وحسن طريقته في طلب العلم."],[175,"وقال الذهبي: برع في هذا الشأن، وكتب عن أقرانه ومن هم دونه، وحصَّل الأصول الكثيرة، وجرَّح وعدَّل، وصحح وعلل، وقيّد وأهمل، مع الديانة والأمانة، والتقوى والصيانة، والورع والتواضع، والصدق والإخلاص، وصحة النقل."],[176,"وقد ألف عددًا من المؤلفات المشهورة، كالأحاديث المختارة، وغيرها."],[177,"توفي سنة ثلاث وأربعين وستمائة."],[178,"٢- أبو القاسم عبد الواحد بن أبي المطهر القاسم بن الفضل الأصبهاني الصيدلاني١."],[179,"سمع من أبيه، وجعفر بن عبد الواحد، وابن أبي ذر الصَّالحاني، وغيرهم."],[180,"حدَّث عنه الضياء المقدسي، وابن خليل، وجماعة."],[181,"قال الذهبي في السير: الشيخ الجليل المسند الرّحلة."],[182,"وقال في تاريخ الإسلام: شيخ مُسند مُعمر مشهور ببلده."],[183,"ولد في ذي الحجة سنة أربع عشرة وخمسمائة."],[184,"وتوفي في جمادى الأولى، سنة خمس وستمائة، عن إحدى وتسعين سنة."],[185,"٣- أبو عَلِيٍّ الْحَسَنِ بْنِ أَحْمَدَ بْنِ الْحَسَنِ الْحَدَّادِ الأصبهاني."],[186,"وهو ثقة حافظ مشهور، ترجم له غير واحد٢، ووصفوه بالحفظ والإتقان، وقد روى عن أبي نعيم الأصبهاني أكثر كتبه."],[187,"قال السمعاني: كان عالمًا ثقة صدوقًا، من أهل العلم والقرآن والدين."],[188,"وقال الذهبي: الشيخ الإمام، المقريء المجود، المحدث المعمر، مسند العصر، شيخ أصبهان في القراءات والحديث جميعًا."],[189,"توفي سنة خمس عشرة وخمسمائة، وقد قارب المائة."],[190,"٤- الحافظ أبو نعيم أحمد بن عبد الله الأصبهاني:"],[191,"إمام حافظ متقن مشهور، صاحب المستخرج، والحلية، ومعرفة الصحابة، وغيرها من المؤلفات الكثيرة النافعة، التي تدل على سعة علمه وإمامته في هذا الشأن."],[192,"وقد ترجم له الكثيرون، وأفرد بعضهم في ترجمته رسائل مستقلة١."],[193,"توفي سنة ثلاثين وأربعمائة."],[194,"٥- أَبُو عَلِيٍّ مُحَمَّدُ بْنُ أَحْمَدَ بْنِ الْحَسَنِ الصَّواف٢:"],[195,"سمع من الإمام الترمذي، وعبد الله بن أحمد بن حنبل، والبرديجي، وغيرهم."],[196,"حدث عنه: أبو بكر البرقاني، وأبو نعيم، وابن بشران، وغيرهم."],[197,"وصفه جميع من ترجم له بالحفظ والإتقان."],[198,"قال الدارقطني: ما رأت عيناي مثل أبي علي بن الصواف."],[199,"وقال ابن أبي الفوارس: كان ثقة مأمونًا، ما رأيت مثله في التحرز."],[200,"وقال الذهبي: الشيخ الإمام المحدث الثقة الحجة."],[201,"كان مولده في سنة سبعين ومائتين."],[202,"وتوفي في شعبان، سنة تسع وخمسين وثلاث مائة."],[203,"سماعات الكتاب"],[204,"جاء في الكتاب سماعات كثيرة، ولذا فسأكتفي ببعضها، فمن ذلك:"],[205,"١- بلغت من أوله سماعًا، بقراءتي على أبي القاسم عبد الواحد بن القاسم ابن الفضل بن عبد الواحد الصيدلاني، بحق إجازته من أبي علي الحداد، في يوم الخميس، ثاني ذي الحجة، من سنة ثمان وتسعين وخمسمائة. كتبه محمد بن عبد الواحد بن أحمد المقدسي، حامدًا لله ومصليًا على محمد وآله."],[206,"٢- سمع جميع ما في هذا الجزء عليّ بقراءة أبي الكرم عبد الرحيم بن علي ابن أحمد بن عبد الواحد بن أحمد المقدسي الفقيه: أبو عبد الله محمد بن عبد الحميد ابن عبد الهادي المقدسي، يوم الجمعة، في العشر الآخرة، من ذي الحجة، سنة خمس وثلاثين وستمائة. كتبه محمد بن أحمد. والحمد لله وحده، وصلى الله على محمد وآله وسلم."],[207,"٣- قرأت من هذا الجزء: حديث البرديجي وما في معناه، على الشيخ الإمام العالم الزاهد الحافظ ضياء الدين أبي عبد الله محمد بن عبد الواحد بن أحمد ابن عبد الرحمن المقدسي، فسمعه أبو بكر يوسف بن أبي الفرج الحراني وأبو النجم بدر بن عبد الله العلائي، وأبو الفضل عمر بن عبد الله بن علي الفارسي، وأبو بكر بن أحمد بن عثمان المقدسي، يوم .... حادي وعشرين، جمادى الأولى، سنة أربعين وستمائة، بالجبل. كتبه يوسف بن الحسن بن بدر بن الحسن النابلسي."],[208,"٤- قرأت جميع هذا الجزء، وفيه: ما روي في الكبائر، لأبي بكر البرديجي وإملاءان عن أبي سعيد بن ملة، وكذلك ما أُلحق به، على الشيخ الإمام العالم الحافظ ضياء الدين أبي عبد الله محمد بن عبد الواحد بن أحمد المقدسي فسمعه الفقيه الإمام مجد الدين محمد بن محمد بن عمر الصفار الاسفراييني وولده عبد الرحمن، وأبو عبد الله محمد بن ثابت بن تاوان بن أحمد التفليسي وذلك يوم السبت، في العشر الأوسط من ربيع الآخر، سنة اثنتين وأربعين وستمائة. كتبه أحمد بن عبد الرحيم بن عبد الواحد بن أحمد المقدسي، حامدًا الله تعالى، ومصليًا على رسوله محمد وآله وأصحابه وسلم."],[209,"٥- سمع جميع هذا الجزء على الشيخ الإمام الحافظ الناقد ضياء الدين أبي عبد الله محمد بن عبد الواحد المقدسي أبقاه الله، بقراءة الإمام العالم شمس الدين أبي العباس أحمد بن محمد بن أمية العبدري، وصح ذلك وكمل في يوم الثلاثاء، ثامن ربيع الآخر، سنة ثنتين وأربعين وستمائة، بمدرسة الشيخ المُسمع. كتبه أحمد ابن عبد الرحمن بن محمد، حامدًا لله ومصليًا على رسوله."],[210,"٦- قرأت هذا جميعه، والذي في حواشيه على صاحبه الحافظ ضياء الدين أبي عبد الله محمد، أثابه الله، بسماعه فيه. وصح وثبت في المحرم سنة سبع وثلاثين وستمائة. كتبه محمد بن عبد الله بن عبد الغني المقدسي."],[211,"نماذج من المخطوط"],[212,"..."],[213,"نماذج من صور المخطوط"],[214,"النص المحقق"],[215,"جُزْءٌ فِيهِ"],[216,"مَنْ رَوَى عَنِ النَّبِيِّ صلى الله عليه وآله وسلم مِنَ الصَّحَابَةِ فِي الْكَبَائِرِ"],[217,"رِوَايَةُ"],[218,"أَبِي بَكْرٍ أَحْمَدَ بْنِ هَارُونَ بْنِ رَوْحٍ الْبَرْدِيجِيِّ"],[219,"رِوَايَةُ أَبِي عَلِيٍّ مُحَمَّدِ بْنِ أَحْمَدَ بْنِ عَبْدِ اللَّهِ الْحَافِظِ عَنْهُ"],[220,"رِوَايَةُ أَبِي عَلِيٍّ الْحَسَنِ بْنِ أَحْمَدَ بْنِ الْحَسَنِ الْحَدَّادِ عَنْهُ"],[221,"رِوَايَةُ أَبِي الْقَاسِمِ عَبْدِ الْوَاحِدِ بْنِ الْقَاسِمِ إِجَازَةً عَنْهُ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ"],[222,"وَلا قُوَّةَ إِلا بِاللَّهِ"],[223,"طُرُقُ أَحَادِيثِ الْكَبَائِرِ"],[224,"أَخْبَرَنَا أَبُو الْقَاسِمِ عَبْدُ الْوَاحِدِ بْنُ الْقَاسِمِ بْنِ الْفَضْلِ بْنِ عَبْدِ الْوَاحِدِ بِقِرَاءَتِي عَلَيْهِ، أَخْبَرَنَا أَبُو عَلِيٍّ الحدَّاد إِجَازَةً، أَخْبَرَنَا أَبُو نُعيم، قَالَ: أَخْبَرَنَا أَبُو عَلِيٍّ مُحَمَّدُ بْنُ أَحْمَدَ بْنِ الْحَسَنِ الصَّواف - رحمه الله - الْبَغْدَادِيُّ، قَالَ: سَمِعْتُ أَبَا بكر أحمد بن هارون بن رَوح البَرّديجي يقول: روى أحد شر رَجُلا مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وآله وسلم عَنِ النَّبِيِّ صلى الله عليه وآله وسلم فِي الْكَبَائِرِ١، وَهُوَ مِمَّا يَدْخُلُ فِي التَّفْسِيرِ عَنِ النَّبِيِّ صلى الله عليه وآله وسلم."],[225,"١- مِنْهُمْ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ:"],[226,"وَهُوَ مَا حَدَّثَنَا الْحَسَنُ بْنُ عَلِيِّ بْنِ عَفَّانَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ نُمَيْرٍ، عَنِ الأَعْمَشِ عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بْنِ شُرحبيل، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ - رضي الله عنه - قَالَ: سُئل النَّبِيُّ صلى الله عليه وآله وسلم عَنِ الْكَبَائِرِ، فَقَالَ: \"أَنْ تُشرك بِاللَّهِ وَهُوَ خَلَقَكَ، وَأَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ أَنْ يَأْكُلَ مَعَكَ، وَأَنْ تَزْنِيَ بِحَلِيلَةِ جَارِكَ\"."],[227,"ثُمَّ قَرَأَ صلى الله عليه وآله وسلم: ﴿وَالذِينَ لاَ يَدْعُونَ مَعَ اللهِ إِلَهًَا آخَر﴾ ١الآيَاتِ."],[228,"لَمْ يَرْوِ هَذَا إِلا ابْنُ نُمَيْرٍ عَلَى لَفْظِ: سُئل النَّبِيُّ صلى الله عليه وآله وسلم عَنِ الْكَبَائِرِ."],[229,"وَرَوَاهُ الثَّوْرِيُّ، وَجَرِيرٌ: أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم سُئل: أَيُّ الكبائر أعظم٢."],[230,"فأخرجه البخاري ٨/٣٥٠ (مع الفتح) كتاب التفسير، باب ﴿وَالذِينَ لاَ يَدْعُونَمَعَ اللهِ إِلَهًَا آخَر﴾، رقم ٤٧٦١، وفي ١٢/١١٦، كتاب الحدود، باب إثم الزناة، رقم ٦٨١١ - ومن طريقه في الموضع الثاني ابن الجوزي في الحدائق ٢/٤٦٤ -، ورواه الترمذي ٥/٣٢٦، كتاب التفسير، باب سورة الفرقان، رقم ٣١٨٢، والنسائي في التفسير من الكبرى ٦/٤٢١، رقم ١٣٦٩، وأبو نعيم في المستخرج (*) ١/١٦٤، رقم ٢٥٨، وفي الحلية ٤/١٤٥، وأبو عوانة ١/٥٥، والبيهقي في الكبرى ٨/١٨، وفي شعب الإيمان ٤/٣٥٤، رقم ٥٣٧٢، وأحمد ١/٤٣٤، والبزار٥/٢٥٩، رقم ١٨٧٥، وعبد الرزاق١٠/٤٦٥، رقم ١٩٧٢٠ - ومن طريقه ابن منده في الإيمان ٢/٥٤٥، رقم ٤٦٧ -، ورواه البغوي في شرح السنة ١/٨٢، رقم ٤٢، وفي تفسيره ١/٤١٩، والطحاوي في شرح مشكل الآثار ٢/ ٣٤٣، ٣٤٤، رقم ٨٨٨، ٨٨٩، والحاكم في معرفة علوم الحديث (ص١٠٠)، والخرائطي في مساوئ الأخلاق (١٥٣)، رقم ٣٩٦، وفي (١٨٠)، رقم٤٨٤، والدارقطني في العلل٥/٢٢٢، ٢٢٣."],[231,"والطبري في تفسيره ١٩/ ٤١، وابن منده في الإيمان٢/٥٤٥، رقم٤٦٧، واللالكائي في شرح أصول اعتقاد أهل السنة ٦/١١٠٤، رقم ١٩٠٢، والخطيب في المهروانيات (ص١١٦)، رقم ٧٧، وفي الفصل للوصل المدرج في النقل ٢/٨٢٧، و٢/٨٤٠."],[232,"كلهم من طريق الثوري."],[233,"والبخاري ١٢/١٩٤ (مع الفتح)، كتاب الديات، باب ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا...﴾، رقم ٦٨٦١، وفي ١٣/٥١٢، كتاب التوحيد، باب قول الله تعالى: ﴿يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ...﴾، رقم ٧٥٣٢- ومن طريقه البغوي في تفسيره ٣/٣٧٧ -، ورواه مسلم١/٩١، كتاب الإيمان، باب كون الشرك أقبح الذنوب، رقم ١٤٢ - ومن طريقه ابن حزم في المحلى ٤/٢٤٥ -، ورواه أبو نعيم في المستخرج ١/١٦٤، رقم ٢٥٨، وأبو يعلى في مسنده ٩/١٠١، رقم ٥١٦٧، والشاشي في مسنده ٢/٢٩، رقم ٤٩٩، و٢/٢٣٠، رقم ٨٠٢، والبيهقي في شعب الإيمان ٤/٣٣٨، رقم ٥٣١٦، والطحاوي في شرح مشكل الآثار ٢/٣٤٥، رقم ٨٩٠، وابن منده في الإيمان ٢/٥٤٤، رقم ٤٦٦، والواحدي في أسباب النزول (ص ٣٤٨، ٣٤٩)، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٢٦."],[234,"من طريق جرير بن عبد الحميد."],[235,"والخطيب في الفصل للوصل المدرج في النقل ٢/٨٢٦. من طريق زيد بن أبي أنيسة، وأبي عبيدة عبد الملك بن معن المسعودي."],[236,"وتابعهم معمر: ذكر ذلك الدارقطني في العلل ٥/٢٢١."],[237,"كما تابعهم أبو يوسف القاضي: ذكر ذلك الخطيب في المهروانيات (ص١١٧) ."],[238,"كلهم عن الأعمش، به."],[239,"قلت: وقد اختلف على الأعمش في هذا الحديث:"],[240,"فرواه ابن نمير، وعدد من الثقات، كما تقدم، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بن شرحبيل، عن ابن مسعود."],[241,"وخالفهم جماعة، فرووه عن الأعمش، عن أبي وائل، عن ابن مسعود:"],[242,"أخرجه النسائي في التفسيرمن الكبرى٦/٤٢٠، رقم ١٣٦٨، وأحمد١/٣٨٠ و٤٣١- ومن طريقه الخطيب في الفصل للوصل المدرج في النقل ٢/٨٢٩-، ورواه البزار ٥/١٠٧، رقم ١٦٨٧، والشاشي في مسنده ٢/٢٧، رقم ٤٩٣، وابن المنذر في الإقناع ١/٣٣٥، رقم ١١٦."],[243,"والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣١.من طريق أبي معاوية."],[244,"وأبو يعلى في مسنده ٩/٣٢، رقم ٥٠٩٨ - وعنه ابن حبان ١٠/٢٦١، رقم ٤٤١٤ -، ورواه الشاشي في مسنده ٢/٢٨، رقم ٤٩٦، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣٠، ٨٣١. من طريق أبي شهاب عبدربه بن نافع الحناط."],[245,"وأحمد ١/٤٣١- ومن طريقه الخطيب في الفصل للوصل المدرج في النقل ٢/٨٢٩-، ورواه الشاشي في مسنده ٢/٨، رقم ٤٩٤، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣١ من طريق أخرى. من طريق وكيع."],[246,"والشاشي في مسنده ٢/٢٤، رقم ٤٨٦، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٢٩، ٨٣٠. من طريق شيبان."],[247,"والشاشي في مسنده ٢/٢٥، رقم ٤٨٧، و٢/٢٨، رقم ٤٩٥، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣٠.من طريق عبد الواحد بن زياد."],[248,"والشاشي في مسنده ٢/٢٨، رقم ٤٩٥، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣٠، ٨٣١، من طريق عبد العزيز بن مسلم."],[249,"والشاشي في مسنده ٢/٢٨، رقم ٤٩٧، والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣١ من طريق قُران بن تمام."],[250,"والشاشي في مسنده (*) ٢/٢٨، رقم ٤٩٨، والخطيب في الفصل للوصل المدرج في النقل٢/٨٣١. من طريق إسماعيل بن زكريا."],[251,"والخطيب في الفصل للوصل المدرج في النقل ٢/٨٣١.من طريق حجوة ابن مدرك."],[252,"كلهم عن الأعمش، به."],[253,"ورواه معمر، عن الأعمش، عن أبي وائل، عن مسروق، عن عبد الله:"],[254,"أخرجه الشاشي في مسنده ٢/٣٠، رقم ٥٠٠، عن إبراهيم الحربي، عن الحسن بن علي، عن عبد الرزاق، عن معمر، به."],[255,"وذكره أبو نعيم في الحلية ٤/١٤٦، من رواية معمر، به."],[256,"قلت: وقد خالف معمر عامة أصحاب الأعمش، والذين رووه بخلاف روايته في الوجهين السابقين، كما إنه قد رواه على الوجه الأول، فيقدم من أقواله ما وافقه فيه غيره."],[257,"وعلى هذا فروايته لهذا الوجه شاذة، والله أعلم."],[258,"ورواه يحيى بن عيسى، عن الأعمش، عن سفيان، عن عبد الله:"],[259,"أخرجه الطبري في تفسيره ١٩/٤٢، عن عيسى بن عثمان بن عيسى الرملي، عن عمه يحيى بن عيسى، به."],[260,"قلت: ويحيى بن عيسى: صدوق يخطيء (التقريب ٧٦١٩)، وقد خالف الثقات الذين رووه في الوجهين الأولين بخلاف روايته."],[261,"وعليه فهذا الوجه منكر، والله أعلم."],[262,"ومما تقدم فلعل الوجهين الأول والثاني محفوظان عن الأعمش، حيث رواه عنه في كلٍ منهما عدد من ثقات أصحابه، ولعله كان يحدث بهما معًا."],[263,"وإلى هذا ذهب غير واحد من الأئمة:"],[264,"قال ابن حبان١٠/٢٦٤: ولست أنكر أن يكون أبو وائل سمعه من عبد الله، وسمعه من عمرو بن شرحبيل عن عبد الله، حتى يكون الطريقان محفوظين."],[265,"وانظر المصادر الآتية بعد قليل."],[266,"كما اختلف على غير الأعمش، مما يطول جدًا ذكره هنا، وانظر لذلك علل الدارقطني ٥/٢٢٠-٢٢٣، المهروانيات (ص١١٦، ١١٧)، وفتح الباري ١١٧، ١١٨."],[267,"٢- وَابْنُ عَبَّاسٍ رضي الله عنه:"],[268,"وَهُوَ مَا حَدَّثَنَاهُ أَحْمَدُ بْنُ عَمْرِو بْنِ أَبِي عَاصِمٍ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنْ شَبيب، عَنْ عِكرمة، عَنِ ابْنِ عَبَّاسٍ – رضي الله عنهما – عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، حَدِيثَ الْكَبَائِرِ."],[269,"وقال فيه: \"والفرار من الزحف\" ١."],[270,"قلت: وروايته عن ابن مسعود جاءت من عدة طرق صحيحة عنه، أخرج أكثرها الطبري في تفسيره، وذكر بعضها ابن كثير في تفسيره، ثم قال: وهو صحيح إليه بلا شك."],[271,"٣- وَعَبْدُ اللَّهِ بْنُ عَمْرٍو:"],[272,"مِنْ طُرق أَصَحُّهَا مَا رَوَاهُ فِراس، عَنِ الشَّعْبِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو – رضي الله عنهما."],[273,"وَرَوَاهُ شُعْبَةُ، وشَيبان، عَنْ فِراس."],[274,"حَدَّثَنَاهُ الْحَسَنُ بْنُ عَلِيِّ بْنِ عَفَّانَ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى [حَدَّثَنَا شَيْبَانُ] ١ عَنْ فِراس."],[275,"وَحَدَّثَنَا أَبُو زرعة، حدثنا عبد اللَّهِ بْنُ مُعاذ، حَدَّثَنَا أَبِي، عَنْ شُعْبَةَ، عَنْ فِرَاسٍ عَنِ الشَّعْبِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو –رضي الله عنهما– أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم قَالَ: \"الْكَبَائِرُ: الشِّرْكُ بِاللَّهِ، وَقَتْلُ النَّفْسِ، وَعُقُوقُ الوالدين\"."],[276,"والبيهقي في الكبرى١٠/٣٥، وفي الصغرى ٤/٩٧، رقم ٤٠٠٥، وابن منده في الإيمان ٢/٥٥٢، رقم ٤٧٩. من طريق محمد بن سايق."],[277,"وعبيد الله بن موسى، ومحمد بن سايق كلاهما عن شيبان، به."],[278,"وأخرجه البخاري ١١/٥٦٤ (مع الفتح)، كتاب الأيمان والنذور، باب اليمين الغموس، رقم ٦٦٧٥ – ومن طريقه البغوي في شرح السنة ١/٨٤، رقم ٤٤، وفي تفسيره ١/٤١٨، وابن الجوزي في البر والصلة (ص٨٨)، رقم ١٠٥، وفي الحدائق ٢/٤٦٥ -، ورواه النسائي ٧/٨٩، كتاب تحريم الدم، باب ذكر الكبائر، رقم ٤٠١١، و٨/٦٣، كتاب القسامة، تأويل قول الله عز وجل: ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا...﴾ رقم ٤٨٦٨، وابن أبي عاصم في كتاب الديات (ص٤٢) – ومن طريقه ابن منده في الإيمان ٢/٥٥٣، رقم ٤٨١-، ورواه أبو نعيم في مسانيد أبي يحيى فراس بن يحيى المكتب (ص٢٨)، رقم ٥/ ٤. من طريق النضر بن شميل."],[279,"والبخاري ١٢/١٩٩٩ (مع الفتح)، كتاب الديات، باب قول الله تعالى: ﴿وَمَنْ أَحْيَاهَا...﴾ رقم ٦٨٧٠، والترمذي ٥/٢٣٦، كتاب التفسير، باب تفسير سورة النساء، رقم ٣٠٢١، والدارمي ٢/١١٢، رقم ٢٣٦٥، وأحمد ٢/٢٠١ - ومن طريقه أبو نعيم في مسانيد أبي يحيى فراس بن يحيى المكتب (ص٢٨)، رقم٥/٢-، ورواه الطبري في تفسيره ٨/٢٤٨، رقم ٩٢٢٢، وابن منده في الإيمان ٢/٥٥٢، رقم٤٨٠، وأبو نعيم في مسانيد أبي يحيى فراس بن يحيى المكتب (ص٢٨)، رقم٥/٣، وقوام السنة في الترغيب والترهيب ٢/١٠٢٢، رقم ٢٥١١.من طريق محمد بن جعفر."],[280,"وأبو نعيم في المستخرج [ولم أقف عليه في المستخرج ١/١٦٤، ١٦٥، حيث ساق طرق الحديث] ٢ (كما في النكت الظراف ٦/٣٤٦)، وفي مسانيد أبي يحيى فراس بن يحيى المكتب (ص٢٨)، رقم ٥/٥. من طريق عبد الله بن المبارك."],[281,"وأبو نعيم في الحلية ٧/٢٠٢، وفي مسانيد أبي يحيى فراس بن يحيى المكتب (ص٢٧)، رقم ٥/١.من طريق داود بن إبراهيم الواسطي."],[282,"وعبد الله بن أحمد في العلل ١/٢١٧، رقم ٤٩٤١، وقوام السنة في الترغيب والترهيب ٢/٩٤٥ رقم ٢٣٠٧.من طريق يحيى بن سعيد."],[283,"كلهم عن شعبة، عن فراس، به."],[284,"٤- وأبو بكرة رضي الله عنه:"],[285,"حدثنا محمدبن عَبْدِ الْمَلِكِ وَغَيْرُهُ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، حَدَّثَنَا الْجَرِيرِيُّ١ عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، عَنْ أَبِيهِ - رضي الله عنه - أَنَّ النبي صلى الله عليه وآله وسلم قال: \"الكبائر: الشِّرْكُ بِاللَّهِ، وَقَتْلُ النَّفْسِ، وَعُقُوقُ الْوَالِدَيْنِ\"."],[286,"ثُمَّ احتفز فقال: \"وشهادة الزور\""],[287,"اعتقاد أهل السنة ٦/١١٠٦، رقم ١٩٠٧، والخطيب في الكفاية (ص١٠٤)، والرافعي في التدوين في أخبار قزوين ٤/٥، وأبو يعقوب الكاتب في المناهي وعقوبات المعاصي (ق١٢٥/ب) . كلهم من طريق بشر بن المفضل."],[288,"والبخاري ١٢/٢٧٦ الموضع السابق، رقم ٦٩١٩، ومسلم ١/٩١، كتاب الإيمان، باب بيان الكبائر وأكبرها، رقم١٤٣ومن طريقه ابن حزم في المحلى ٤/٢٤٥، و١١/٢٦٩، وابن عبد الهادي في مسألة التوحيد (ص٧٥)، رقم ٤١، ورواه البيهقي في الكبرى ١٠/١٢١، وأحمد ٥/٣٦، ٣٨- ومن طريقه ابن الجوزي في البر والصلة (ص٨٧)، رقم ١٠٣، وفي الحدائق ٢/٤٦٤-، ورواه البزار ٩/٩٧، رقم ٣٦٢٩، والطبري في تهذيب الآثار (مسند علي) رقم ٢٩٦، وابن منده في الإيمان ٢/٥٤٧، رقم ٤٧١، والواحدي في الوسيط ٢/٣٩، ٤٠."],[289,"من طريق إسماعيل بن علية."],[290,"والبخاري ١٠/٤١، كتاب الأدب، باب عقوق الوالدين من الكبائر، رقم ٥٩٧٦، والبيهقي في الشعب ٦/١٨٨، رقم ٧٨٦٦. من طريق خالد الطحان."],[291,"وأبو نعيم في المستخرج ١/١٦٥، رقم ٢٦٠.من طريق أبي بشر."],[292,"والبيهقي في الكبرى ١٠/١٢١، وفي شعب الإيمان ٦/١٨٨، رقم ٧٨٦٦، والخرائطي في مساؤي الأخلاق، رقم ١٥٣ (*)، ورقم ٢٤٤، وابن منده في الإيمان٢/٥٤٦، رقم ٤٧٠، وقوام السنة في الترغيب والترهيب١/٦٩، رقم٨٨. من طريق يزيد بن هارون."],[293,"والبزار ٩/٩٧، رقم ٣٦٣٠، والطحاوي في شرح مشكل الآثار ٢/٣٤٧، رقم٨٢.من طريق عبد الوهاب بن عطاء."],[294,"وابن المنذر في تفسيره (بهامش تفسير ابن أبي حاتم) (ق١٣٠/أ) من طريق وهيب."],[295,"كلهم عن سعيد بن إياس الجريري، به، نحوه."],[296,"وقال الترمذي: هذا حديث حسن صحيح."],[297,"وقال البزار: وهذا الحديث لا نعلمه يروى عن أبي بكرة إلا من حديث الجريري، ورواه عن الجريري غير واحد، فاقتصرنا على حديث إسماعيل بن إبراهيم."],[298,"٥- وَأَبُو هُرَيْرَةَ مِنْ ثَلاثَةِ أَوْجُهٍ:"],[299,"فَأَحْسَنُ ذَلِكَ مَا حَدَّثَنَا الرَّبِيعُ بْنُ سُلَيْمَانَ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي سُلَيْمَانُ بْنُ بِلالٍ، عَنْ كَثِيرِ بْنِ زَيْدٍ، عَنِ الْوَلِيدِ بْنِ رَبَاح، عَنْ أَبِي هُرَيْرَةَ -رضي الله عنه - قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: \"اتَّقُوا السَّبْعَ الْمُوبِقَاتِ\"."],[300,"قُلْنَا: وَمَا هنَّ؟."],[301,"قَالَ: \"الشِّرْكُ بِاللَّهِ، وَقَتْلُ النَّفْسِ الَّتِي حرَّم اللَّهُ إِلا بِالْحَقِّ، وَالزِّنَا، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَشَهَادَةُ الزُّورِ، وَقَذْفُ الْمُحْصَنَاتِ الْغَافِلاتِ الْمُؤْمِنَاتِ\"."],[302,"وَلَيْسَ فِي كُلِّ الْحَدِيثِ ذِكْرُ١: \"قَذْفِ الْمُحْصَنَاتِ\"إِلا في هذا."],[303,"حجر في موافقة الخُبر الخَبر١/٣٤٩-، ورواه قوام السنة في الترغيب والترهيب ٢/٩٤٤، رقم ٢٣٠٥."],[304,"من طريق أبي العباس محمد بن يعقوب."],[305,"والخطيب في الكفاية (ص١٠٢)، واللالكائي في شرح أصول اعتقاد أهل السنة ٦/١١٠٥، رقم ١٩٠٤.من طريق عبد الله بن أحمد بن إسحاق."],[306,"والطحاوي في شرح مشكل الآثار ٢/٣٤٩، رقم ٨٩٤."],[307,"والسهمي في تاريخ جرجان (ص٤٩٥)، رقم ١٠٠٢، عن أبي يعقوب يوسف بن محمد الاستراباذي."],[308,"كلهم عن الربيع بن سليمان، عن ابن وهب، عن سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة."],[309,"وتوبع الربيع بن سليمان على هذا الوجه:"],[310,"أخرجه مسلم ١/٩٢، كتاب الإيمان، باب بيان الكبائر وأكبرها، رقم ١٤٥- ومن طريقه ابن حزم في المحلى ٤/٢٤٥، و٨/٣٢٦، ٤٦٨، و١١/٢٦٨، ٤٠٠، وابن عبد الهادي في مسألة التوحيد (ص٧٦)، رقم ٤٢-، ورواه البيهقي في شعب الإيمان ٤/٥٠، رقم ٤٣٠٩. من طريق هارون بن سعيد الأيلي."],[311,"وأبو داود ٣/٢٩٤، كتاب الوصايا، باب ما جاء في التشديد في أكل مال اليتيم، رقم ٢٨٧٤- ومن طريقه أبو يعقوب الكاتب في المناهي وعقوبات المعاصي (ق١٠٥/أ) -، عن أحمد بن سعيد الهمداني."],[312,"كلاهما عن ابن وهب، به."],[313,"كما توبع ابن وهب:"],[314,"أخرجه البخاري٥/٤٦٢ (مع الفتح)، كتاب الوصايا، باب قول الله تعالى: ﴿إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا...﴾، رقم ٢٧٦٦، وفي ١٠/٢٤٣، كتاب الطب، باب الشرك والسحر من الموبقات، رقم ٥٧٦٤، وفي ١٢/١٨٨، كتاب الحدود، باب رمي المحصنات، رقم ٦٨٥٧ - ومن طريقه ابن حبان ١٢/٣٧١، رقم٥٥٦١، والبغوي في شرح السنة١/٨٦، رقم٤٥، وفي تفسيره١/٤١٩."],[315,"وابن أبي عاصم في الجهاد ٢/٦٤٦، رقم٢٧٣، وابن الجوزي في الحدائق ٢/٤٦٣، وابن حجر في موافقة الخُبر الخَبر ١/٣٤٩ (كلهم من طريق البخاري) ورواه أبو نعيم في المستخرج ١/١٦٥، رقم ٢٦٢، وأبو عوانة ١/٥٥، والبيهقي في الكبرى ٦/٢٨٤، و٨/٢٤٩، و٩/٧٦، وفي شعب الإيمان ١/٢٦٥، رقم ٢٨٤ و٥/٢٧٩، رقم ٦٦٥٨، وفي المدخل إلى السنن (ص٢٣٩)، رقم ٣٢٢، وابن منده في الإيمان ٢/٥٥٠، رقم ٤٧٦."],[316,"كلهم من طريق عبد العزيز بن عبد الله الأويسي."],[317,"والطحاوي في شرح مشكل الآثار ٢/٣٤٩، رقم ٨٩٥.من طريق عبد الله ابن محمد الفهمي."],[318,"كلاهما عن سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة."],[319,"قلت: والوجه الثاني أرجح، حيث رواه عدد من الثقات، وفيهم أئمة حفاظ كذلك، كما توبع الربيع عليه من عدد من الثقات، وأخرجه هذه المتابعات البخاري ومسلم."],[320,"في حين لم أجد من تابع المصنف في روايته لهذا الوجه، فروايته شاذة، والله أعلم."],[321,"٦- وَأَنَسُ بْنُ مَالِكٍ رضي الله عنه:"],[322,"حَدَّثَنَا سُلَيْمَانُ بْنُ سَيْفٍ، حَدَّثَنَا أَبُو عتَّاب الدَّلال، حدثنا شعبةح."],[323,"وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا أَبُو دَاوُدَ، حَدَّثَنَا شُعْبَةُ، عَنْ عُبَيْدِ الله ابن أَبِي بَكْرِ بْنِ أَنَسٍ، عَنْ أَبِيهِ – رضي الله عنه – قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: \"أَكْبَرُ الْكَبَائِرِ: الشِّرْكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ الَّتِي حرَّم اللَّهُ إلا بالحق\""],[324,"طريق وهب بن جرير."],[325,"والبخاري ٥/٣٠٩ (مع الفتح)، كتاب الشهادات، باب ما قيل في شهادة الزور، رقم٢٦٥٣، والبيهقي في الكبرى ١٠/١٢١، وابن منده في الإيمان ٢/٥٤٨، رقم ٤٧٤.من طريق عبد الملك بن إبراهيم الجدي."],[326,"والبخاري ١٢/١٩٩ (مع الفتح)، كتاب الديات، باب قول الله تعالى: ﴿وَمَنْ أَحْيَاهَا...﴾، رقم ٦٨٧١.من طريق عبد الصمد."],[327,"ومسلم ١/٩١، كتاب الإيمان، باب بيان الكبائر وأكبرها، رقم ١٤٤، والترمذي ٣/٥٠٤، كتاب البيوع، باب ما جاء في التغليظ في الكذب والزور ونحوه، رقم ١٢٠٧، وفي ٥/٢٣٥، كتاب التفسير، تفسير سورة النساء، رقم ٣٠١٨، والنسائي ٧/٨٨، كتاب تحريم الدم، باب ذكر الكبائر، رقم ٤٠١٠، و٨/٦٣، كتاب القسامة، تأويل قول الله عز وجل: ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا...﴾، رقم ٤٨٦٧، والطبري في تفسيره ٨/٢٤٨، رقم ٩٢٢٠، وفي تهذيب الآثار (مسند علي)، رقم ٢٩٥، وابن منده في الإيمان ٢/٥٤٨، رقم ٤٧٤.من طريق خالد بن الحارث."],[328,"والنسائي٧/٨٨، كتاب تحريم الدم، باب ذكر الكبائر، رقم٤٠١٠، و٨/٦٣، كتاب القسامة تأويل قول الله عز وجل: ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا...﴾ رقم ٤٨٦٨.من طريق النضر بن شُميل."],[329,"وأبو نعيم في المستخرج ١/١٦٥، رقم ٢٦١.من طريق روح بن عبادة."],[330,"والبيهقي في الكبرى ٨/٢٠، وفي ١٠/١٢١، و١٠/١٩٧، وفي الصغرى ٣/٢٠٣، رقم ٢٩٢٤، والحربي في غريب الحديث ١/٤٣، وابن منده في الإيمان ٢/٥٤٨ رقم ٤٧٤، وابن الحطاب الرازي في مشيخته (ص١٣٩)، رقم ٣٥- ومن طريقه الذهبي في تذكرة الحفاظ ٤/١٤٤٣-. من طريق عمر ابن مرزوق."],[331,"وأحمد ٣/١٣٤- ومن طريقه ابن حجر في تغليق التعليق ٥/٣٨٥-، ورواه اللالكائي في شرح أصول اعتقاد أهل السنة ٦/١١٠٥، رقم ١٩٠٥، ١٩٠٦. من طريق بهز بن أسد."],[332,"وابن منده في الإيمان ٢/٥٤٨، رقم ٤٧٣ ومن طريقه ابن حجر في تغليق التعليق ٣/٣٨٤-، ورواه أبو سعيد النقاش في كتاب الشهود (كما في الفتح ٥/٣١٠) - ومن طريقه ابن حجر في التغليق٥/٣٨٥-. من طريق أبي عامر العقدي."],[333,"وابن منده في الإيمان ٢/٥٤٨، رقم٤٧٤.من طريق بشر بن عمرو، ويحيى ابن حبيب، ومحمد بن عبد الأعلى."],[334,"والطبري في تفسيره ٨/٢٤٨، رقم ٩٢٢١. من طريق يحيى بن كثير."],[335,"كلهم عن شُعْبَةُ، عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرِ، عن أنس، نحوه."],[336,"وخالفهم روح بن عبادة، فرواه عن شعبة، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، عَنْ أنس:"],[337,"ذكر ذلك الترمذي، في الموضع السابق، ولم أقف على من أخرجه."],[338,"قال الترمذي - بعد إخراجه للوجه السابق -: هذا حديث حسن غريب صحيح ورواه روح بن عبادة عن شعبة، وقال: عن عبد الرحمن بن أبي بكرة، ولا يصح."],[339,"قلت: وقد تقدمت رواية روح بن عبادة عند أبي نعيم في المستخرج، وقد وافق من رواه على الوجه الأول، فيقدم من روايتيه ما وافقه فيه غيره، ولعل الحمل في روايته الثانية على أحد الرواة عنه، والله أعلم."],[340,"٧- وَعِمْرَانُ بْنُ حُصين رضي الله عنه:"],[341,"حَدَّثَنَا أَبُو زُرْعَةَ، حَدَّثَنَا الْحَسَنُ بْنُ بِشْرٍ، حَدَّثَنَا الْحَكَمُ بْنُ عَبْدِ الْمَلِكِ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ عِمْرَانَ بْنِ حُصَيْنٍ - رضي الله عنه - قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: \"مَا تَعُدُّونَ الْكَبَائِرَ فِيكُمْ؟ \"."],[342,"قُلْنَا: الشِّرْكُ بِاللَّهِ، وَالزِّنَا، وَالسَّرِقَةُ، وَشُرْبُ الْخَمْرِ."],[343,"قَالَ: \"هُنَّ كَبَائِرُ، وَفِيهِنَّ عُقُوبَاتٌ، أَلا أُنَبِّئُكُمْ بِأَكْبَرِ الكبائر\"."],[344,"قلنا: بلى. قال: \"شهادة الزور\""],[345,"كلهم، عن سعيد بن بشير، عن قتادة، عن الحسن، عن عمران، نحوه."],[346,"وقال البيهقي: تفرد به عمر بن سعيد الدمشقي، وهو منكر الحديث، وإنما يعرف من حديث النعمان بن مرة مرسلًا."],[347,"قلت: وفي هذا الكلام نظر، حيث لم يتفرد به عمر بن سعيد، وإنما تابعه عدد من الرواة، ورواية النعمان لا تعارض هذه الرواية، بل تشهد لها."],[348,"ولذا قال الحافظ ابن حجر في موافقة الخُبر ١/٣٥٦، بعد ذكره لقول البيهقي المتقدم، قال: كذا قال، ولم ينفرد به كما ترى، بل تابعه عليه ثقتان."],[349,"وقال ابن أبي الفوارس: هذا حديث غريب من حديث قتادة عن الحسن، تفرد به الحكم بن عبد الملك."],[350,"وتعقبه ابن حجر في موافقة الخبر فقال: قد تقدم من طريق سعيد بن بشير، فلم ينفرد به الحكم."],[351,"وقال الهيثمي في المجمع ١/ ١٠٣: رجاله ثقات، إلا أن الحسن مدلس وعنعنه."],[352,"وقال ابن حجر في الفتح ١٢/١٩٠: سنده حسن."],[353,"وقال في موافقة الخبر ١/٣٥٦: هذا حديث حسن غريب من حديث الحسن، عزيز من حديث قتادة... له شاهد مرسل من حديث النعمان بن مرة...، ولآخره شاهد في الصحيحين من حديث أبي بكرة."],[354,"قلت: إسناده ضعيف، فالحسن لم يسمع من عمران بن حصين (المراسيل ص ٣٨) ."],[355,"وخولف قتادة في روايته للوجه السابق:"],[356,"فرواه يونس بن عبيد، والسري بن يحيى، عن الحسن، مرسلًا:"],[357,"أخرجه المروزي في زياداته على كتاب البر والصلة لابن المبارك (ص١٤٣)، رقم ١٠٥، عن يزيد بن زريع، عن يونس بن عبيد، عن الحسن مرسلًا."],[358,"وأخرجه إسماعيل القاضي في أحكام القرآن (كما في موافقة الخبر١/٣٥٩)، من طريق يونس بن عبيد، والسري بن يحيى، عن الحسن مرسلًا."],[359,"قلت: ولعل الحمل في هذا الاختلاف على الحسن، فهو معروف بكثرة الإرسال والتدليس، فلعله كان يرويه مرة عن عمران، ومرة بإسقاطه، والله أعلم."],[360,"وله شاهد قوي، ولكنه مرسل:"],[361,"أخرجه مالك في الموطأ ١/١٦٧ - ومن طريقه ابن عبد البر في جامع بيان العلم وفضله١/٤٨٠، رقم ٧٦٥، وابن حجر في موافقة الخُبر الخَبر ١/٣٦٠."],[362,"وعبد الرزاق ٢/ ٣٧١، رقم ٣٧٤٠، عن ابن عيينة."],[363,"كلاهما عن يحيى بن سعيد، عن النعمان بن مرة، عن النبي صلى الله عليه وآله وسلم نحوه مختصرًا، وزاد فيه: \"وأسوأ السرقة الذي يسرق صلاته...\" الحديث."],[364,"وقال الحافظ ابن حجر: هذا حديث مرسل قوي الإسناد شاهد لحديث الحسن، يعتضد كل منهما بالآخر. ولآخره شاهد في الصحيح من حديث أبي هريرة."],[365,"قلت: ولعل هذا الشاهد يرقى بالحديث إلى الحسن لغيره، والله أعلم."],[366,"٨- وخُريم بْنُ فَاتِكٍ رضي الله عنه:"],[367,"حَدَّثَنَا سُلَيْمَانُ بْنُ سَيْفٍ، وَمُحَمَّدُ بْنُ إِسْحَاقَ: أَبُو بكر، قالا: حدثنا يعلى ابن عُبَيْدٍ، حَدَّثَنَا سُفْيَانُ العَصْفُري، عَنْ أَبِيهِ، عَنْ حَبيب بن النعمان، عن خُرَيم ابن فَاتِكٍ – رضي الله عنه – أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم أصبح ذات يوم بعدما صَلَّى الْغَدَاةَ فَقَالَ: \"عَدَلَتْ شَهَادَةُ الزُّورِ الشِّرْكَ بِاللَّهِ وَعُقُوقَ الْوَالِدَيْنِ\". ثُمَّ قَرَأَ: ﴿فَاجْتَنِبُوا الرِّجْسَ مِنْ الأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ﴾ ١."],[368,"أماليه ١/٩٢، رقم ١٧٧، والخطيب في تلخيص المتشابه ١/١٦٠، وابن عساكر في تاريخ دمشق١٠/٣٩، ويعقوب بن سفيان في المعرفة والتاريخ ٣/١٢٩، وأبو يعقوب الكاتب في المناهي وعقوبات المعاصي (ق١٢٥/أ، ب) . كلهم من طريق محمد بن عبيد."],[369,"ويعلى بن عبيد، ومحمد بن عبيد، كلاهما عن سفيان بن زياد، به نحوه."],[370,"وقال الترمذي: وهذا عندي أصح، وخريم بن فاتك له صحبة، وقد رَوَى عَنِ النَّبِيِّ صلى الله عليه وآله وسلم أحاديث وهو مشهور."],[371,"قلت: وقد اختلف على سفيان بن زياد في هذا الحديث:"],[372,"فرواه يعلى بن عبيد، ومحمد بن عبيد، كما تقدم، عن سفيان بن زياد، عَنْ أَبِيهِ، عَنْ حَبِيبِ بْنِ النُّعْمَانِ، عَنْ خريم بن فاتك."],[373,"ومحمد بن عبيد، ويعلى كلاهما ثقة (التقريب ٦١١٤، ٧٨٤٤) ."],[374,"ورواه مروان بن معاوية، عن سفيان، عن فاتك بن فضالة، عن أيمن ابن خريم:"],[375,"أخرجه الترمذي ٤/٥٤٧، الموضع السابق، رقم ٢٢٩٩- ومن طريقه ابن الأثير في أسد الغابة ١/١٦٠ -. عن أحمد بن منيع."],[376,"وأحمد٤/١٧٨، ٢٣٣، ٣٢٢ومن طريقه أبو نعيم في معرفة الصحابة٢/٣٧٤ رقم٩٩٦، وابن قانع في معجم الصحابة١/٥٣، والمزي في تهذيب الكمال٣/٤٤٦، ٤٤٧، وابن عساكر في تاريخ دمشق (*) ١٠/٣٨. كلهم من طريق أحمد"],[377,"والبغوي في معجم الصحابة (ق١٣) – ومن طريقه ابن عساكر في تاريخ دمشق ١٠/٣٨، والواحدي في الوسيط ٣/٢٧٠-. عن جده."],[378,"وابن عساكر في تاريخ دمشق١٠/٣٩، والمزي في تهذيب الكمال٢٣/١٣٥ من طريق أيوب بن محمد الوزان (*) وأبو نعيم في معرفة الصحابة ٢/٣٧٤، رقم ٩٩٦. من طريق سويد بن سعيد."],[379,"والطبري في تفسيره ١٧/١٥٤، عن أبي كريب."],[380,"كلهم عن مروان بن معاوية، عن سفيان، عن فاتك، عن أيمن بن خريم."],[381,"وقال الترمذي: وهذا حديث غريب، إنما نعرفه من حديث سفيان بن زياد، واختلفوا في رواية هذا الحديث عن سفيان بن زياد، ولا نعرف لأيمن بن خريم سماعًا من النبي صلى الله عليه وآله وسلم (**)"],[382,"وقال ابن معين في تاريخه٢/ ١٤٧: الحديث كما حدَّث به محمد بن عبيد. ومروان بن معاوية لم يُقمه."],[383,"وقال يعقوب بن سفيان في المعرفة ٣/١٣٠: وقد خالف مروان محمدًا، والصحيح رواية محمد."],[384,"قلت: ومروان بن معاوية: ثقة حافظ (التقريب ٦٥٧٥) ."],[385,"ورواه أبو أسامة، عن سفيان بن زياد، عن أبيه، عن خريم بن فاتك:"],[386,"أخرجه الطبري في تفسيره ١٧/١٥٤، عن أبي السائب، عن أبي أسامة، به."],[387,"قلت: وأبو أسامة، هو حماد بن أسامة: ثقة ثبت، كان بأخرة يحدث من كتب غيره (التقريب ١٤٨٧) ."],[388,"وأبو السائب، هو سلم بن جنادة: ثقة ربما خالف (التقريب٢٤٦٤) ."],[389,"ورواه سلمة بن رجاء، عن سفيان، عن أبيه، عن ابن خريم بن ثابت، عن أبيه:"],[390,"ذكره أبو نعيم في معرفة الصحابة ٢/٣٧٥، ولم أقف على من أخرجه."],[391,"قلت: وسلمة بن رجاء: صدوق يُغرب (التقريب ٢٤٩٠) ."],[392,"ولعل الوجه الأول أرجح هذه الأوجه، حيث رواه ثقتان كذلك، في حين لم أقف على من تابع رواته في بقية الأوجه."],[393,"وإسناده من هذا الوجه الراجح ضعيف، فيه زياد العصفري، والد سفيان، وهو مجهول، قال ابن القطان في بيان الوهم والإيهام ٣/٥٤٨: مجهول."],[394,"وقال الذهبي في الميزان ٢/٩٦: لا يدرى من هو."],[395,"وله طريق أخرى عن خريم، ولكنها لا تثبت:"],[396,"فقد أخرجه العقيلي في الضعفاء ٣/٤٣٣. من طريق عمرو بن زياد الباهلي، عن غالب بن غالب، عن أبيه، عن جده، عن جندب، عن خريم بن فاتك، نحوه."],[397,"وقال العقيلي: غالب بن غالب عن أبيه عن جده، إسناده مجهول، لا يعرف إلا بهذا الحديث."],[398,"ثم قال: هذا يروى عن خريم بن فاتك بإسناد صالح من غير هذا الوجه."],[399,"٩- وَابْنُ عُمَرَ رضي الله عنهما:"],[400,"حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى الأَشِيبُ، حدثنا أيوب ابن عُتْبَةَ، عَنْ طَيْسَلة، عَنِ ابْنِ عُمَرَ - رضي الله عنهما - عَنِ النَّبِيِّ صلى الله عليه وآله وسلم قَالَ: \"الْكَبَائِرُ سَبْعٌ، الشِّرْكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَالزِّنَا، وَالسِّحْرُ، وَالْفِرَارُ مِنَ الزَّحْفِ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ\"."],[401,"هَكَذَا رَوَاهُ مَرْفُوعًا."],[402,"وروى هذا الْحَدِيثَ عَنْ طَيْسَلَةَ: يَحْيَى بْنُ أَبِي كَثِيرٍ، وَزِيَادُ بْنُ مِخْرَاقٍ، عَنْ طَيْسَلَةَ، عَنِ ابْنِ عُمَرَ رضي الله عنهما مَوْقُوفًا."],[403,"وَهُوَ طَيْسَلة بْنُ ميَّاس، وَمَياسٌ لَقَبٌ، وَهُوَ طَيْسَلَةُ بْنُ علي الحنفي١ والبيهقي في الكبرى٣/٤٠٩، والخرائطي في مساويء الأخلاق رقم٢٤٦، و٧٤٠- ومن طريقه ابن حجر في موافقة الخُبر الخَبر ١/٣٤٤-، ورواه الخطيب في الكفاية (ص١٠٥) . من طريق حسين بن محمد المروذي."],[404,"وأبو القاسم البغوي في الجعديات ٢/٤٨٠، رقم ٣٣٣٩ – ومن طريقه ابن عبد البر في التمهيد ٥/٦٩-، عن علي بن الجعد."],[405,"كلهم عن أَيُّوبُ بْنُ عُتْبَةَ، عَنْ طَيْسَلَةَ، عَنِ ابْنِ عمر، مرفوعًا."],[406,"ورواه سلم بن سلام، عن أَيُّوبُ بْنُ عُتْبَةَ، عَنْ طَيْسَلَةَ، عَنِ ابْنِ عمر، موقوفًا:"],[407,"أخرجه الطبري ٨/٢٤٠، رقم ٩١٨٨، وفي تهذيب الآثار (مسند علي)، رقم ٣١٤، عن سليمان بن ثابت الخزاز، عن سلم بن سلام، عن أيوب بن عتبة، به، موقوفًا."],[408,"وتوبع أيوب بن عتبة على هذا الوجه:"],[409,"أخرجه البخاري في الأدب المفرد (١٧)، رقم ٨- ومن طريقه ابن الجوزي في البر والصلة (ص١١٢)، رقم ١٤٢، ببعضه، وابن حجر في موافقة الخُبر الخَبر ١/٣٤٣-، ورواه الطبري في تفسيره ٨/٢٣٩، رقم ٩١٨٧، وأبو يعقوب الكاتب في المناهي وعقوبات المعاصي (ق١٠٥/أ)، وإسحاق بن راهويه في مسنده وفي تفسيره، وإسماعيل القاضي في أحكام القرآن (كما في موافقة الخُبر الخَبر١/٣٤) . كلهم من طريق إسماعيل بن علية."],[410,"والبخاري في الأدب المفرد (ص٢٥)، رقم ٣١، ببعضه، وابن المنذر في تفسيره (بهامش تفسير ابن أبي حاتم (ق١٣٠/ب) . من طريق حماد بن سلمة."],[411,"وإسماعيل بن علية، وحماد، كلاهما عن زياد بن مخراق."],[412,"وتابع زيادًا على هذا الوجه: يحيى بن أبي كثير:"],[413,"ذكر ذلك المصنف هنا، وابن عبد البر في التمهيد ٥/٦٩."],[414,"كلاهما، عن طيسلة بن مياس، عن ابن عمر، موقوفًا."],[415,"وقال الحافظ ابن حجر في موافقة الخبر: هذا حديث حسن غريب لا نعرفه إلا من حديث طيسلة، وهو بفتح الطاء المهملة، وسكون التحتانية وفتح السين المهملة، وتخفيف اللام، ووهم من قدَّم اللام على السين ... الخ."],[416,"ثم قال: والموقوف أصح إسنادًا."],[417,"وقال أيضًا: وأقوى طرقه رواية زياد بن مخراق الأولى."],[418,"ورواه عيسى بن خالد، وسلم بن سلام، عن أيوب بن عتبة، عن يحيى ابن أبي كثير، عن عبيد بن عمير، عن أبيه، مرفوعًا:"],[419,"أخرجه الطبراني في الكبير١٧/٤٨، رقم ١٠٢.من طريق عيسى بن خالد اليمامي."],[420,"والطبري في تفسيره ٨/٢٤١، رقم ٩١٨٩، وفي تهذيب الآثار (مسند علي)، رقم ٣١٥.من طريق سلم بن سلام."],[421,"كلاهما عن أيوب بن عتبة، به."],[422,"وخولف أيوب في روايته لهذا الوجه عن يحيى، خالفه حرب بن شداد، فرواه عن يحيى بن أبي كثير، عن عبد الحميد بن سنان، عن عبيد بن عمير، عن أبيه."],[423,"وقد تكلمت عن هذه المخالفة بالتفصيل في تحقيقي لتتمة الضياء المقدسي على هذا الكتاب، ولم أر أن أذكرها هنا مراعاة للاختصار."],[424,"ولعل الحمل في هذا الاختلاف على أيوب نفسه، فهو ضعيف (التقريب ٦١٩)، ولعله كان يحدث بهذه الأوجه جميعًا."],[425,"ولكن من حيث الترجيح عمومًا عن طيسلة فالوجه الثاني أرجح، حيث توبع أيوب عليه من ثقتين، وهما زياد بن مخراق، ويحيى بن أبي كثير (التقريب ٢٠٩٨، ٧٦٣٢) ."],[426,"وعليه فالراجح أنه موقوف على ابن عمر، ولم يثبت مرفوعًا، والله أعلم."],[427,"١٠- وَأَبُو أَيُّوبَ رضي الله عنه:"],[428,"حَدَّثَنَا يَزِيدُ بْنُ عَبْدِ الْمَلِكِ، حَدَّثَنَا يَزِيدُ بْنُ عَمْرٍو السَّكُونِيُّ، حَدَّثَنَا بَقِيَّةُ، حَدَّثَنَا ابْنُ ثَوْبَانَ، عَنْ أبيه، عن محكول يَرُدُّهُ إِلَى١ أَبِي أَيُّوبَ – رضي الله عنه – أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم قَالَ: \"أَكْبَرُ الْكَبَائِرِ: الإِشْرَاكُ بِاللَّهِ، وَقَتْلُ النَّفْسِ، وَعُقُوقُ الْوَالِدَيْنِ، وَمَنْعُ ابْنِ السَّبِيلِ، وَالْفِرَارُ مِنَ الزَّحْفِ\" ٢."],[429,"وأحمد ٥/٤١٣، والطبراني في الكبير ٤/١٢٨، رقم ٣٨٨٥، وفي مسند الشاميين ٢/١٧٨، رقم ١١٤٤- ومن طريقه الشجري في أماليه ١/٢٠-. من طريق حيوة بن شريح."],[430,"وأحمد ٥/٤١٣. من طريق زكريا بن عدي."],[431,"والطبراني في الكبير٤/١٢٨، رقم ٣٨٨٥ ومن طريقه الشجري في أماليه ١/٢٠ من طريق عيسى ابن المنذر."],[432,"واللالكائي في شرح أصول اعتقاد أهل السنة ٦/١١٣٤، رقم ١٩٧٩، من طريق عبد الرحمن بن يونس السراج."],[433,"كلهم عن بقية، عن بَحِيْر بن سعد، عن خالد بن مَعْدَان، عن أبي رُهْم السَّمعِي، عن أبي أيوب الأنصاري، أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم قَالَ: \"من مات يعبد الله لا يشرك به شيئًا، ويقيم الصلاة، ويؤتي الزكاة، ويجتنب الكبائر كان له الجنة\" فسألوه عن الكبائر، فقال: \"الإشراك بالله، وقتل النفس المسلمة، والفرار يوم الزحف\"."],[434,"ورواه أكثر من ثقة، عن بقية، عن بَحِيْر بن سعد، عن خالد بن مَعْدَان عن أبي المتوكل، عن أبي هريرة:"],[435,"أخرجه ابن أبي عاصم في كتاب الجهاد ٢/٢٠٠، رقم ٢٧٨، وفي كتاب الديات (ص٤٢) - وعنه أبو الشيخ في التوبيخ والتنبيه١ (٢٣٣)، رقم٢١١ ورواه ابن أبي حاتم في العلل ١/٣٣٩، رقم ١٠٠٥."],[436,"من طريق محمد بن مصفى، وعمرو بن عثمان."],[437,"وابن أبي حاتم في الموضع السابق من العلل. من طريق عبد الجبار بن عاصم."],[438,"وابن شاهين في الأفراد (كما في أطراف المسند ٨/١٨) ومن طريقه ابن الجوزي في التحقيق ٢/٣٨٣، رقم ٢٠٢٨ من طريق داود بن رشيد."],[439,"كلهم عن بقية، عن بَحِيْر بن سعد، عن خالد بن مَعْدَان، عن أبي المتوكل، عن أبي هريرة، أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم قَالَ: \"من لقي الله لا يشرك به شيئًا، وأدى زكاة ماله طيبًا بها نفسه، محتسبًا، وسمع وأطاع، فله الجنة – أو دخل الجنة - وخمس ليس لهن كفارة: الشرك بالله، وقتل النفس بغير حق، أو بهت مؤمن، أو الفرار يوم الزحف، أو يمين صابرة تقتطع مالًا بغير حق\"."],[440,"ورواه إسحاق بن راهويه، وهشام بن عمار، عن بقية، عن بَحِيْر بن سعد، عن خالد بن مَعْدَان، عن المتوكل، عن أبي هريرة:"],[441,"أخرجه إسحاق بن راهويه في مسنده ١/٣٤٢، رقم ٣٣٦."],[442,"والطبراني في مسند الشاميين ٢/٢٠٠، رقم ١١٨٣، ١١٨٤، وابن أبي حاتم في العلل (١) ١/٣٣٩، رقم ١٠٠٥، من طريق هشام بن عمار."],[443,"كلاهما عن بقية، عن بَحِيْر بن سعد، به."],[444,"وتوبع بقية على هذا الوجه:"],[445,"أخرجه الطبراني في مسند الشاميين ٢/٢٠٠، رقم ١١٨٣، ١١٨٤، عن أحمد بن المعلى الدمشقي، عن هشام بن عمار، عن إسماعيل بن عياش وبقية، به."],[446,"قلت: وأحمد بن المعلى: صدوق (التقريب ١٠٨) توفي سنة ٢٨٦."],[447,"وهشام بن عمار: صدوق كبر فصار يتلقن (التقريب ٧٣٠٣)، وتوفي سنة ٢٤٥."],[448,"وعلى هذا فبين وفاته ووفاة أحمد بن المعلى أكثر من أربعين سنة، فاحتمال أن تكون رواية أحمد عنه إنما كانت حال تغيره وبعد كبره قوي جدًا."],[449,"وعليه ففي ثبوت هذه المتابعة نظر، وخاصة أن ابن أبي حاتم قد روى هذا الحديث عن أبي زرعة، عن هشام بن عمار لوحده، وأبو زرعة ثقة ثبت كما هو معلوم، وروايته مقدمة على رواية أحمد بن المعلى، والله أعلم."],[450,"ورواه زكريا بن عدي، عن بقية، عن بَحِيْر بن سعد، عن خالد بن مَعْدَان، عن المتوكل، أو أبي المتوكل، عن أبي هريرة:"],[451,"أخرجه أحمد (١) ٢/٣٦١، ٣٦٢- ومن طريقه عبد الغني المقدسي في كتاب التوحيد (٦٨) رقم ٧١-، عن زكريا بن عدي، عن بقية به، على الشك."],[452,"قلت: وزكريا بن عدي: ثقة (التقريب ٢٠٢٤) ."],[453,"وقال الحافظ ابن حجر في تعجيل المنفعة (ص٢٥٦)، رقم ١٠٠٤:المتوكل، أو أبو المتوكل، كذا وقع بالشك، عن أبي هريرة حديث: \"من لقي الله لا يشرك به شيئًا\" الحديث، وفيه: \"وخمس ليس لهن كفارة\"، روى عنه خالد بن معدان، وذكره ابن حبان في الثقات، فقال: لا أدري من هو، ولا ابن من هو."],[454,"قلت (أي ابن حجر): وقد أخرج ابن شاهين في كتاب الأفراد الحديث الذي له في المسند، فقال: عن أبي المتوكل، ولم يشك، ولم أره في كتاب الحاكم أبي أحمد في الكنى، فظن ابن الجوزي أنه أبو المتوكل الناجي المخرج له في الصحيح، فاحتج بحديثه هذا في التحقيق، فوهم في ذلك، وقد جزم البخاري، وتبعه ابن أبي حاتم بأنه المتوكل، اسم لا كنية، وقال أبو حاتم: مجهول، وهذا هو المعتمد. انتهى."],[455,"قلت: إن كان مراد الحافظ قوله: \"وهذا هو المعتمد\" ترجيح أنه المتوكل، وأنه اسم لا كنية، ففي ذلك نظر، حيث تقدم في التخريج أن من قال: \"أبو المتوكل\" أكثر ممن قال بأنه: \"المتوكل\". وهذا يقتضي ترجيح رواياتهم."],[456,"وهذا ما رجحه أبو زرعة كما تقدم بقوله: \"أبو المتوكل أصح\". ولعله الصواب."],[457,"ولكن أحد رواته على الوجه الآخر، وهو ابن راهويه ثقة ثبت، فلعل الحمل في هذا الاختلاف على بقية، إذ الرواة عنه في كل الأوجه أقوى منه حالًا."],[458,"ويؤيد ذلك أنه رواه أيضًا عند الإمام أحمد على الشك، فتأكد أنه كان يرويه مرة على وجه، ومرة على وجه آخر، ومرة ثالثة بالشك بينهما، والله أعلم."],[459,"ورواه حيوة بن شريح، عن بقية، عن بحير بن سعد، عن خالد بن معدان، عن أبي بحرية، عن معاذ بن جبل:"],[460,"أخرجه الطبراني في مسند الشاميين ٢/١٨٧، رقم ١١٦١، عن أحمد بن محمد بن يحيى بن حمزة، عن حيوة بن شريح، به."],[461,"قلت: وأحمد بن محمد، قال عنه الذهبي: له مناكير (الميزان ١/١٥١) ."],[462,"وعليه فهذا الوجه منكر، حيث خالف الثقات في هذه الرواية، والله أعلم."],[463,"ومما تقدم يتضح أن بقية قد رواه على عدة أوجه، والرواة عنه في كل هذه الأوجه - ما عدا الوجه السادس - كلهم أقوى منه حالًا، فلعل الحمل في هذا الاختلاف عليه، فكان يحدث بها جميعًا، وهذا يدل على اضطرابه فيها."],[464,"وبقية كماهومعلوم مشهور بتدليس التسوية، ولم يصرح بالتحديث في أيّ منها."],[465,"إلا أنه قد توبع على الوجه الثاني، تابعه ابن أبي السري:"],[466,"فقد أخرجه الطبري في تفسيره ٨/٣٤٩، رقم ٩٢٢٤، عن ابن أبي السري: محمد بن المتوكل عن بحير بن سعد (١)، عن خالد بن معدان، به."],[467,"ومحمد بن المتوكل: صدوق له أوهام كثيرة (التقريب ٦٢٦٣) ."],[468,"وله طريق أخرى من رواية أبي رهم عن أبي أيوب:"],[469,"أخرجه الطبراني في الكبير ٤/١٢٩، رقم ٣٨٨٦- ومن طريقه الشجري في أماليه ١/٢١-. عن عمرو بن إسحاق الحمصي."],[470,"وابن أبي عاصم في الجهاد ٢/٦٤٥، رقم ٢٧٢، عن محمد بن عوف."],[471,"كلاهما عن محمد بن إسماعيل بن عياش، عن أبيه، عن ضَمْضَم بن زرعة، عن شريح بن عبيد، عن أبي رهم، عن أبي أيوب، نحوه."],[472,"قلت: وإسناده لا بأس به، وإن كان فيه محمد بن إسماعيل، وهو ضعيف (انظر الجامع في الجرح ٢/٤٥٠)، وقيل إنه لم يسمع من أبيه، لكن إحدى طريقي الحديث من رواية محمد بن عوف عنه، وقد قال الحافظ في التهذيب: \"وقد أخرج أبو داود عن محمد بن عوف عنه عن أبيه عدة أحاديث، لكن يروونها بأن محمد بن عوف رآها في أصل إسماعيل\" (التهذيب ٩/٦١) ."],[473,"وله طريق أخرى عن أبي أيوب:"],[474,"وقد خرجتها بالتفصيل في الذيل عن الكبائر، وإسنادها صحيح لغيره."],[475,"ومما تقدم فلعل الحديث بمجموع الطرق السابقة يكون صحيحًا لغيره، والله أعلم."],[476,"١١- عبد الله بن أنيس رضي الله عنه:"],[477,"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْمُغِيرَةِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ صَالِحٍ، حَدَّثَنَا اللَّيْثُ، عَنْ هِشَامِ بْنِ سَعْدٍ، عَنْ مُحَمَّدِ بْنِ زَيْدٍ. ح."],[478,"وَحَدَّثَنَا ابْنُ سَهْلٍ١، حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ زَيْدِ بْنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ، عَنْ أَبِي أُمَامَةَ الأَنْصَارِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ رضي الله عنه عَنِ النَّبِيِّ صلى الله عليه وآله وسلم: \"اتَّقُوا الْكَبَائِرَ، فَإِنَّهُنَّ سَبْعٌ: الإِشْرَاكُ بِاللَّهِ، وَقَتْلُ النَّفْسِ الَّتِي حرَّم اللَّهُ إِلا بِالْحَقِّ، وَالزِّنَا، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالْفِرَارُ مِنَ الزَّحْفِ، وَعُقُوقُ الْوَالِدَيْنِ\""],[479,"تَمَّ بحمد الله ومنه المختارة ٩/١٥، رقم ٢، وابن الجوزي في البر والصلة (٨٨)، رقم ١٠٦، والمزي في تهذيب الكمال ٣٣/٥١، ٥٢-، ورواه ابن أبي شيبة في مسنده ٢/٣٤٦، رقم ٨٥٠، وفي المصنف ٧/٥ (بمتنه الأخير الآتي) - وعنه ابن أبي عاصم في الآحاد والمثاني ٤/٨٠، رقم ٢٠٣٦-، ورواه الطحاوي في شرح مشكل الآثار ٢/٣٤٨، رقم ٨٩٣، والخرائطي في مساوئ الأخلاق، رقم ١٢٤ (بمتنه الأخير)، وابن المنذر في تفسيره، وعبد بن حميد في تفسيره – كما في هامش تفسير ابن أبي حاتم (ق ١٣٠/ب) - كلهم من طريق يونس بن محمد المؤدب."],[480,"والطبراني في الكبير ١٣ (القسم المتمم) ص١٤٢، رقم ٣٤٩، وفي الأوسط٤/١٥٠ رقم ٣٢٦١- وعنه أبو نعيم في الحلية ٧/٣٢٧-. من طريق شعيب ابن يحيى."],[481,"كلهم (عبد الله بن صالح، ويونس، وشعيب) عن الليث بن سعد، عَنْ هِشَامِ بْنِ سَعْدٍ، عَنْ مُحَمَّدِ بْنِ زيد، عن أبي أمامة، عن عبد الله بن أنيس."],[482,"وجاء متنه عند أكثرهم: \"أكبر الكبائر الإشراك بالله – عز وجل - وعقوق الوالدين، واليمين الغموس، وأيم الله الذي نفسي بيده لا يحلف أحدٌ وإن كان على مثل جناح البعوضة إلا كانت نكتة في قلبه إلى يوم القيامة\"."],[483,"وقال الترمذي: وأبو أمامة الأنصاري، هو ابن ثعلبة، ولا نعرف اسمه، وقد رَوَى عَنِ النَّبِيِّ صلى الله عليه وآله وسلم أحاديث، وهذا حديث حسن غريب."],[484,"وقال الحاكم: هذا حديث صحيح الإسناد، ولم يخرجاه. ووافقه الذهبي."],[485,"وقال الطبراني في الأوسط: لا يروى هذا الحديث عن عبد الله بن أنيس إلا بهذا الإسناد، تفرد به الليث."],[486,"وقال أبو نعيم: غريب من حديث الليث وهشام، وما رواه عن النبي صلى الله عليه وآله وسلم بهذا اللفظ إلا [ابن] (١) أنيس."],[487,"أما الطريق الثانية:"],[488,"فقد اختلف على وهب بن بقية فيها على ثلاثة أوجه:"],[489,"فرواه أسلم بن سهل، عن وهب بن بقية، عن خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ عَبْدِ الرَّحْمَنِ ابن إسحاق، عن محمد بن زيد، عَنْ أَبِي أُمَامَةَ الأَنْصَارِيِّ، عَنْ عَبْدِ اللَّهِ بن أنيس:"],[490,"أخرجه المصنف هنا – ومن طريقه الضياء المقدسي في المختارة ٩/١٦، رقم ٣ - عن أسلم بن سهل، عن وهب بن بقية، به."],[491,"قلت: وأسلم بن سهل، هو الواسطي، الراجح أنه ثقة ثبت (١)"],[492,"ورواه أكثر من ثقة، عن وَهْبُ بْنُ بَقِيَّةَ، حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ زَيْدِ بْنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ، عن عبد الله ابن أبي أمامة، عن عبد الله بن أنيس:"],[493,"أخرجه ابن حبان ١٢/٣٧٤، رقم ٥٥٦٣، والضياء في المختارة ٩/١٧، رقم ٤، وابن الأثير في أسد الغابة ٣/١٢٠. من طريق أبي يعلى الموصلي."],[494,"والطبراني في الكبير (٢) القسم المتتم للجزء ١٣/٤١٢، رقم ٣٥٠- ومن طريقه الضياء في المختارة ٩/١٧، رقم ٥- عن محمود بن محمد الواسطي."],[495,"وابن أبي عاصم في الآحاد والمثاني ٤/٨٠، رقم ٢٠٣٥ (١)، وفي ٥/٢٠، رقم ٢٥٥٦.كلهم عن وهب بن بقية، به."],[496,"قلت: وأبو يعلى، وابن أبي عاصم: ثقتان ثبتان معروفان."],[497,"ومحمود الواسطي قال الذهبي: الحافظ المفيد العالم، وكان من بقايا الحفاظ ببلده (السير ١٤/٢٤٢) ."],[498,"ورواه البغوي، وإبراهيم بن إسحاق، عن وهب بن بقية، عن خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ عَبْدِ الرَّحْمَنِ بن إسحاق، عن محمد بن زيد، عن عبد الله بن أبي أمامة الأنصاري، عن أبي أمامة، عن عبد الله بن أنيس:"],[499,"أخرجه أبو القاسم البغوي في معجم الصحابة (ق ٣٧٠) ."],[500,"وأبو يعقوب الكاتب في المناهي (ق١١٤/أ، ب)، عن إبراهيم بن إسحاق."],[501,"كلاهما عن وهب بن بقية، به."],[502,"وذكره المزي في تحفة الأشراف٤/٢٧٥، من رواية عبد الرحمن بن إسحاق، به."],[503,"وقال المزي: فزاد فيه: \" عبد الله بن أبي أمامة \"."],[504,"قلت: والبغوي ثقة حافظ معروف."],[505,"وإبراهيم بن إسحاق، لعله السراج، وهو ثقة (السير ١٣/٤٨٩) ."],[506,"قلت: ولعل الوجه الثاني أرجح عن وهب، حيث رواه الأكثر كذلك، مع ثقتهم."],[507,"إلاإنه يمكن القول بأن الوجهين الأول والثالث محفوظان عن وهب، إذ الرواة ف يهما ثقات، ولعل الحمل في هذا الاختلاف على عبد الرحمن بن إسحاق، وهو صدوق (التقريب ٣٨٠٠)، والرواة دونه في كل الأوجه أوثق منه، والله أعلم."],[508,"ولكن الوجه الأول أرجح عمومًا، حيث توبع عبد الرحمن بن إسحاق، تابعه هشام بن سعد، كما تقدم في تخريج الطريق الأولى، والله أعلم."],[509,"وإسناده من هذا الوجه صحيح لغيره، فعبد الرحمن، تقدم أنه صدوق، وهشام بن سعد: صدوق له أوهام (التقريب ٥٨٩٤) . وأبو أمامة: صحابي جليل."],[510,"مصادر ومراجع"],[511,"..."],[512,"فهرس المصادر والمراجع"],[513,"أولًا: المصادر المخطوطة:"],[514,"١- حديث أبي الحسن الحمامي: علي بن أحمد، رواية أبي الحسن العلاف الحاجب عنه، الجزء الخامس، مصورة عندي عن مصورة جامعة الإمام، رقم ٧٢٣٦ (١٤٦-١٥٥) ."],[515,"٢-الذيل على الكبائر، للضياء المقدسي: محمد بن عبد الواحد، مصورة عندي عن نسخة الظاهرية، مجموع رقم ٨١ (١- ٥) ."],[516,"٣- معجم الصحابة، للبغوي: أبي القاسم عبد الله بن محمد، مصورة عندي، عن نسخة الخزانة العامة بالرباط."],[517,"٤- المناهي وعقوبات المعاصي والتحذير منها، لأبي يعقوب محمد بن إسحاق الكاتب، مصورة عندي عن نسخة الظاهرية، رقم ٤٥٨٥ عام (١-٢٠٣) ."],[518,"ثانيًا: المصادر المطبوعة:"],[519,"١- الآحاد والمثاني، لابن أبي عاصم، أبي بكر أحمد بن عمرو (ت ٢٨٧)، تحقيق د. باسم الجوابرة، دار الراية، الرياض، الطبعة الأولى١٤١١؟ – ١٩٩١م."],[520,"٢- الأحاديث المختارة، للحافظ ضياء الدين المقدسي (ت٤٦٣)، تحقيق عبد الملك بن دهيش، مكتبة النهضة الحديثة، مكة المكرمة، الطبعة الأولى ١٤١١؟."],[521,"٣- الإحسان في تقريب صحيح ابن حبان (ت٣٥٤؟)، ترتيب علاء الدين علي بن بلبان الفارسي (ت٧٣٩)، تحقيق شعيب الأرنأوط، مؤسسة الرسالة، بيروت، الطبعة الأولى ١٤٠٨؟."],[522,"٤- أحكام القرآن، لأبي بكر أحمد بن علي الجصاص (ت ٣٧٠)، مراجعة صدقي محمد جميل، المكتبة التجارية، مكة المكرمة، ١٤١٤؟."],[523,"٥- الأدب المفرد، للإمام البخاري، محمّد بن إسماعيل (ت٢٥٦؟)، مع شرحه فضل الله الصمد، المطبعة السلفية، القاهرة، الطبعة الثانية، ١٣٨٨؟."],[524,"٦- كتاب الأربعين حديثًا، لأبي بكر الآجري، محمد بن الحسين (ت٣٦٠؟)، تحقيق بدر البدر، مكتبة المعلا، الكويت، الطبعة الأولى ١٤٠٨؟."],[525,"٧- إرشاد طلاب الحقائق، للإمام النووي: أبي زكريا يحيى بن شرف (ت٦٧٦؟)، تحقيق عبد الباري السلفي، مكتبة الإيمان، المدينة النبوية، الطبعة الأولى ١٤٠٨؟."],[526,"٨- الاستيعاب في معرفة الأصحاب، لأبي عمر يوسف بن عبد البر (ت٤٦٣؟)، تحقيق د. طه الزيني، مطبوع بهامش الإصابة، مكتبة الكليات الأزهرية، القاهرة، الطبعة الأولى ١٣٩٧؟."],[527,"٩- أسد الغابة في معرفة الصحابة، للإمام ابن الأثير الجزري (ت٦٣٠؟) تصوير دار إحياء التراث العربي، بيروت."],[528,"١٠- الإصابة في تمييز الصحابة، للحافظ ابن حجر العسقلاني، أحمد بن علي، تحقيق د. طه الزيني، مكتبة الكليات الأزهرية، القاهرة، الطبعة الأولى ١٣٩٧؟."],[529,"١١- أصول السنة، لابن أبي زمنين، محمد بن عبد الله الأندلسي (ت٣٩٩؟)، تحقيق عبد الله البخاري، مكتبة الغرباء الأثرية، المدينة النبوية، الطبعة الأولى ١٤١٥؟."],[530,"١٢- إطراف المسند المعتلي بأطراف المسند الحنبلي، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق زهير الناصر، دار ابن كثير، ودار الكلم الطيب، بيروت، الطبعة الأولى ١٤١٤؟."],[531,"١٣- الاعتقاد والهداية إلى سبيل الرشاد، للإمام البيهقي، أحمد بن الحسين (ت٤٥٨؟)، تعليق كمال الحوت، عالم الكتب، بيروت، الطبعة الثانية ١٤٠٥؟."],[532,"١٤- الإقناع، لابن المنذر: أبي بكر محمد بن إبراهيم (ت٣١٨؟)، تحقيق د. عبد الله الجبرين، مطابع الفرزدق، الطبعة الأولى ١٤٠٨؟."],[533,"١٥-الأمالي، لابن بشران: عبد الملك بن محمد (ت٤٣٠؟)، تحقيق عادل العزازي، دار الوطن، الرياض، الطبعة الأولى ١٤١٨؟."],[534,"١٦-الأمالي، للإمام يحيى بن الحسين الشجري، ترتيب محمد بن أحمد العبشمي، مطبعة الفجالة، مصر، بدون سنة طبع."],[535,"١٧- الأنساب، للإمام السمعاني، عبد الكريم بن محمد (ت٥٦٢؟)، تعليق عبد الله البارودي دار الكتب العلمية، بيروت، الطبعة الأولى ١٤٠٨ – ١٩٨٨م."],[536,"١٨- كتاب الإيمان، للحافظ ابن منده: محمد بن إسحاق (ت٣٩٥)، تحقيق د. علي الفقيهي، مطبوعات الجامعة الإسلامية، المدينة النبوية، الطبعة الأولى، ١٤٠١؟."],[537,"١٩- البحر الزخار (مسند البزار)، للحافظ أبي بكر أحمد بن عمرو البزار (ت٢٩٢؟)، تحقيق محفوظ السلفي، مؤسسة علوم القرآن، بيروت، الطبعة الأولى، بدء في طبعه عام ١٤٠٩؟، وصدر منه حتى الآن تسعة أجزاء، ولم يكتمل بعد."],[538,"٢٠- كتاب البر والصلة، لابن الجوزي، أبي الفرج عبد الرحمن بن علي (ت٥٩٧؟)، تحقيق عادل عبد الموجود، علي معوض، مكتبة السنة، القاهرة، الطبعة الأولى ١٤١٣؟."],[539,"٢١- بغية الباحث عن زوائد مسند الحارث، للحافظ نور الدين الهيثمي (ت ٨٠٧؟)، تحقيق د. حسين الباكري، مطبوعات مركز خدمة السنة، المدينة النبوية، الطبعة الأولى ١٤١٣؟."],[540,"٢٢- بغية الطلب في تاريخ حلب، لابن العديم: عمر بن أحمد (ت٦٦٠؟)، تحقيق د. سهيل زكار، دار الفكر، بيروت، لبنان، لم تذكر سنة الطبع."],[541,"٢٣- بيان الوهم والإيهام الواقعين في كتاب الأحكام، للحافظ ابن القطان الفاسي (ت٦٢٨؟) تحقيق د. الحسين آيت سعيد، دار طيبة، الرياض، الطبعة الأولى ١٤١٨؟."],[542,"٢٤- التاريخ، للإمام يحيى بن معين (ت٢٣٣؟)، تحقيق د. أحمد نور سيف، مركز البحث العلمي، جامعة الملك عبد العزيز، الطبعة الأولى ١٣٩٩؟ – ١٩٧٩م."],[543,"٢٥- تاريخ بغداد، للخطيب البغدادي، أحمد بن علي بن ثابت (ت٤٦٣؟)، تصوير دار الكتاب العربي، بيروت."],[544,"٢٦- تاريخ التراث العربي، لفؤاد سزكين، تعريب محمود حجازي، طبعة جامعة الإمام محمد بن سعود الإسلامية، الرياض، ١٤٠٣؟ ١٩٨٧م."],[545,"٢٧- تاريخ جرجان، لأبي القاسم حمزة بن يوسف السهمي (ت٤٢٧؟)، بعناية محمد عبد المعيد خان، عالم الكتب، بيروت، الطبعة الرابعة ١٤٠٧؟ – ١٩٨٧م."],[546,"٢٨- تاريخ دمشق، لابن عساكر: علي بن الحسن الشافعي (ت٥٧١؟)، تحقيق عمرو غرامة العمروي، دار الفكر، بيروت، الطبعة الأولى، ١٤١٥؟."],[547,"٢٩- التاريخ الكبير، للإمام البخاري، محمد بن إسماعيل (ت٢٥٦؟)، تصوير دار الكتب العلمية، بيروت."],[548,"٣٠- تحفة الأشراف بمعرفة الأطراف، للحافظ المزي: يوسف بن عبد الرحمن (ت٧٤٢؟)، تحقيق عبد الصمد شرف الدين، الدار القيمة، الهند، الطبعة الثانية ١٤٠٣؟ – ١٩٨٣م."],[549,"٣١- التحقيق في أحاديث الخلاف، لأبي الفرج ابن الجوزي (ت٥٩٧؟)، تحقيق مسعد السعدني، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤١٥؟."],[550,"٣٢- التدوين في أخبار قزوين، للإمام عبد الكريم بن محمد الرافعي (ت٦٢٣؟)، تحقيق عزيز الله العطاردي، مطبعة العزيزية، حيدر آباد، الطبعة الأولى ١٤٠٤؟."],[551,"٣٣- الترغيب والترهيب، للحافظ عبد العظيم بن عبد القوي المنذري (ت٦٥٦؟)، تحقيق مصطفى عمارة، المكتبة العصرية، بيروت ١٤٠٥؟."],[552,"٣٤- الترغيب والترهيب، للإمام إسماعيل بن محمد الأصبهاني، قوام السنة (ت٥٣٥؟)، تحقيق محمد زغلول، ومحمود زايد، مكتبة النهضة الحديثة، مكة المكرمة."],[553,"٣٥- تعجيل المنفعة بزوائد رجال الأئمة الأربعة، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق عبد الله هاشم المدني، دار المحاسن للطباعة، ١٣٨٦؟."],[554,"٣٦-تغليق التعليق، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق سعيد القزقي، المكتب الإسلامي، بيروت، دار عمار، الأردن، الطبعة الأولى ١٤٠٥؟."],[555,"٣٧- تفسير البغوي (معالم التنزيل)، للإمام الحسين بن مسعود البغوي (ت٥١٦؟)، تحقيق خالد العك ومروان سوار، دار المعرفة، بيروت، الطبعة الثانية ١٤٠٧؟."],[556,"٣٨- تفسير الطبري (جامع البيان عن تأويل آي القرآن)، لأبي جعفر محمد بن جرير الطبري (ت٣١٠؟)، مطبعة مصطفى بابي الحلبي، مصر."],[557,"٣٩- تفسير الطبري (جامع البيان عن تأويل آي القرآن)، لأبي جعفر محمد بن جرير الطبري (ت٣١٠؟)، تحقيق محمود شاكر، أحمد شاكر، دار المعارف، مصر."],[558,"٤٠- تفسير القرآن العظيم، للحافظ إسماعيل بن كثير (ت٧٤٧؟) قدم له يوسف مرعشلي، دار المعرفة، بيروت، الطبعة الأولى ١٤٠٧؟."],[559,"٤١- تفسير القرآن العظيم، لابن أبي حاتم الرازي (ت٣٢٧؟) تحقيق أسعد الطيب، مكتبة نزار الباز، مكة المكرمة، الرياض، الطبعة الأولى، ١٤١٧؟."],[560,"٤٢- تقريب التهذيب، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق محمد عوامة، دار الرشيد، سوريا، الطبعة الأولى ١٤٠٦؟ – ١٩٨٦م."],[561,"٤٣- التقييد والإيضاح لما أطلق وأغلق من كتاب ابن الصلاح، للعراقي: عبد الرحيم بن الحسين (ت٨٠٦؟)، مؤسسة الكتب الثقافية، بيروت، الطبعة الأولى ١٤١١؟."],[562,"٤٤- تلخيص المتشابه في الرسم، للخطيب البغدادي، أحمد بن علي (ت٤٦٣؟)، تحقيق سكينة الشهابي، دار طلاس للترجمة، دمشق، الطبعة الأولى ١٩٨٥م."],[563,"٤٥- التمهيد لما في الموطأ من المعاني والأسانيد، للحافظ أبي عمر بن عبد البر القرطبي (ت٤٦٣؟)، تحقيق سعيد اعراب وآخرين، طبعة وزارة الأوقاف المغربية."],[564,"٤٦- تنبيه الغافلين عن أعمال الجاهلين، لابن النحاس: أحمد بن إبراهيم الدمشقي (ت٨١٤؟)، طبع على نفقة مريم الدعيج، مطابع الرياض، شارع المرقب."],[565,"٤٧- تهذيب الآثار، للإمام الطبري: محمد بن جعفر (ت٣١٠؟)، تحقيق محمود شاكر، مطبعة المدني، مصر."],[566,"٤٨- تهذيب التهذيب، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، مصورة عن طبعة دائرة المعارف العثمانية، الهند."],[567,"٤٩- تهذيب الكمال في أسماء الرجال، للمزي: يوسف بن عبد الرحمن (ت٨٤٢؟)، تحقيق بشار عواد، مؤسسة الرسالة، بيروت، الطبعة الأولى."],[568,"٥٠- التوبيخ والتنبيه، لأبي الشيخ الأصبهاني: عبد الله بن محمد بن حيان (ت٣٦٩؟) تحقيق أبي الأشبال حسين المندوه، مكتبة التوعية الإسلامية، مصر، الطبعة الأولى ١٤٠٨؟."],[569,"٥١- التوحيد لله عز وجل، لعبد الغني بن عبد الواحد المقدسي (ت٦٦٠؟)، تحقيق محمد النابلسي، عبد الأكرم السقا، دار السقا، دمشق، الطبعة الأولى ١٤١٨؟."],[570,"* جامع البيان عن تأويل آي القرآن، انظر: تفسير الطبري."],[571,"٥٢- جامع بيان العلم وفضله، لابن عبد البر الأندلسي (ت٤٦٣؟)، تحقيق أبي الأشبال الزهيري، دار ابن الجوزي، الدمام، الطبعة الأولى ١٤١٥؟."],[572,"٥٣- جامع المسانيد والسنن، للحافظ ابن كثير، إسماعيل بن عمر (ت٧٧٤؟) تحقيق عبد المعطي قلعجي، دار الفكر، بيروت، الطبعة الأولى ١٤١٥؟."],[573,"٥٤- الجامع في الجرح والتعديل، جمع وترتيب أبي المعاطي النوري وآخرين، عالم الكتب، بيروت، الطبعة الأولى ١٤١٢؟."],[574,"٥٥- الجرح والتعديل، للإمام عبد الرحمن بن أبي حاتم الرازي (ت٣٢٧؟)، تحقيق عبد الرحمن المعلمي، مصورة عن طبعة دائرة المعارف العثمانية، الطبعة الأولى ١٣٧٢؟."],[575,"٥٦- الجعديات (حديث علي بن الجعد)، لأبي القاسم البغوي (ت٣١٧؟)، تحقيق رفعت فوزي، مكتبة الخانجي، القاهرة، الطبعة الأولى ١٤١٥؟."],[576,"٥٧- كتاب الجهاد، لابن أبي عاصم: أحمد بن عمر النبيل (ت٢٨٧؟)، تحقيق د. مساعد الراشد الحميد، دار القلم، دمشق، الطبعة الأولى، ١٤٠٩؟."],[577,"٥٨- الجواب الكافي عن الدواء الشافي، لابن القيم: محمد بن أبي بكر (ت٧٥١؟)، تحقيق سعيد اللحام، مكتبة المعارف، الرياض، الطبعة الأولى ١٤٠٧؟."],[578,"٥٩- الحدائق في علم الحديث والزهديات، لأبي الفرج ابن الجوزي (ت٥٩٧؟)، تحقيق مصطفى السبكي، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤٠٨؟."],[579,"٦٠- حلية الأولياء، للحافظ أبي نعيم الاصبهاني، أحمد بن عبد الله (ت٤٣٠؟)، دار الكتاب العربي، بيروت، الطبعة الرابعة ١٤٠٥؟ - ١٩٨٥م."],[580,"٦١- الدر المنثور في التفسير بالمأثور، للإمام جلال الدين السيوطي (ت٩١١؟)، دار الفكر، بيروت، الطبعة الأولى ١٤٠٣؟ – ١٩٨٣م."],[581,"٦٢- ذكر أخبار إصبهان، للحافظ أبي نعيم الأصبهاني (ت٤٣٠؟)، الدار العلمية، الهند، الطبعة الثانية ١٤٠٥؟ – ١٩٨٥م."],[582,"٦٣- الزواجر عن اقتراف الكبائر، لابن حجر الهيثمي: أبي العباس أحمد بن محمد المكي (ت٩٧٤)، مكتبة نزار الباز، مكة المكرمة، الطبعة الأولى ١٤١٧؟."],[583,"٦٤- سنن الترمذي، للإمام أبي عيسى محمد بن عيسى الترمذي (ت٢٧٩؟)، تحقيق أحمد شاكر وآخرين، مطبعة مصطفى البابي الحلبي، مصر، الطبعة الثانية ١٣٩٥؟."],[584,"٦٥- سنن الدارقطني، للإمام أبي الحسن علي بن عمر الدارقطني (ت٣٨٥؟)، تحقيق عبد الله هاشم المدني، حديث أكادمي، فيصل آباد، باكستان."],[585,"٦٦- سنن الدارمي، للإمام عبد الله بن عبد الرحمن الدارمي (ت٢٥٥؟)، تحقيق عبد الله هاشم المدني، دار المحاسن للطباعة، القاهرة ١٣٨٦؟ – ١٩٦٦م."],[586,"٦٧- سنن ابن ماجه، لأبي عبد الله محمد بن يزيد القزويني (ت٢٧٥؟)، تحقيق محمد فؤاد عبد الباقي، المكتبة الإسلامية، استانبول."],[587,"٦٨- سنن أبي داود، للإمام سليمان بن الأشعث السجستاني (ت٢٧٥؟) تحقيق عزت الدعاس، نشر محمد علي السيد، حمص، الطبعة الأولى ١٣٩١؟."],[588,"٦٩- السنن الصغرى، للإمام البيهقي: أحمد بن الحسين (ت٤٥٨؟)، تحقيق عبد المعطي قلعجي، جامعة الدراسات الإسلامية، باكستان، الطبعة الأولى ١٤١٠؟ – ١٩٨٩م."],[589,"٧٠- السنن الكبرى، للإمام البيهقي، مصورة عن الطبعة الهندية، دار المعرفة، بيروت."],[590,"٧١- السنن الكبرى، للإمام النسائي، أحمد بن شعيب (ت٣٠٣؟)، تحقيق عبد الغفار البنداري، وسيد كسروي، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤١١؟."],[591,"٧٢- سنن النسائي الصغرى (المجتبى)، للإمام النسائي (ت٣٠٣؟) باعتناء عبد الفتاح أبو غدة، دار البشائر الإسلامية، بيروت، الطبعة الثانية ١٤٠٦؟ – ١٩٨٦م."],[592,"٧٣- سير أعلام النبلاء، للإمام الذهبي، محمد بن أحمد (ت٧٤٨؟)، تحقيق شعيب الأرنأوط وآخرين، مؤسسة الرسالة، بيروت، الطبعة الأولى."],[593,"٧٤- شذرات الذهب في أخبار من ذهب، لابن العماد الحنبلي (ت١٠٨٩؟)، تحقيق محمود الأرنأوط، دار ابن كثير، دمشق، الطبعة الأولى ١٤٠٦؟."],[594,"٧٥- شرح أصول اعتقاد أهل السنة والجماعة، لأبي القاسم هبة الله بن الحسن الطبري اللالكائي (ت٤١٨؟)، تحقيق أحمد الغامدي، دار طيبة، الرياض، الطبعة الثالثة، ١٤١٥؟."],[595,"٧٦- شرح السنة، للإمام الحسين بن مسعود البغوي (ت٥١٦؟)، تحقيق شعيب الأرنأوط، المكتب الإسلامي، بيروت، الطبعة الثانية ١٤٠٣؟ – ١٩٨٣م."],[596,"٧٧- شرح مشكل الآثار، لأبي جعفر الطحاوي، أحمد بن محمد (ت٣٢١؟)، تحقيق شعيب الأرنأوط، مؤسسة الرسالة، بيروت، الطبعة الأولى ١٤٠٨؟."],[597,"٧٨- شعب الإيمان، للإمام البيهقي، أحمد بن الحسين (ت٤٥٨؟)، تحقيق محمد السعيد زغلول، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤١٠؟."],[598,"٧٩- صحيح البخاري، المطبوع مع فتح الباري، انظر: فتح الباري."],[599,"٨٠- صحيح ابن خزيمة، للإمام أبي بكر محمد بن إسحاق بن خزيمة (ت٣١١؟)، تحقيق د. محمد مصطفى الأعظمي، المكتب الإسلامي، الطبعة الثانية١٤٠١؟."],[600,"٨١- صحيح مسلم، للإمام مسلم بن الحجاج النيسابوري (ت٢٦١؟)، تحقيق محمد فؤاد عبد الباقي، المكتبة الإسلامية، استانبول، الطبعة الأولى ١٣٧٤؟ – ١٩٥٥م."],[601,"٨٢- الضعفاء الكبير، لأبي جعفر محمد بن عمرو العقيلي (ت٣٢٢؟)، تحقيق عبد المعطي قلعجي، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤٠٤؟."],[602,"٨٣- طبقات الأسماء المفردة، للبرديجي: أحمد بن هارون (ت٣٠١؟)، تحقيق سكينة الشهابي، دار طلاس للدراسات والترجمة، دمشق، الطبعة الأولى ١٩٨٧م."],[603,"٨٤- طبقات المحدثين بأصبهان، لأبي الشيخ الأصبهاني (ت٣٦٩)، تحقيق عبد الغفور البلوشي، مؤسسة الرسالة، بيروت، الطبعة الأولى ١٤٠٨؟."],[604,"٨٥- علل الحديث، لابن أبي حاتم الرازي، عبد الرحمن بن محمد (ت٣٢٧؟)، دار المعرفة، بيروت ١٤٠٥؟ – ١٩٨٥م."],[605,"٨٦- العلل ومعرفة الرجال، للإمام أحمد بن حنبل (ت٢٤١؟)، تحقيق وصي الله عباس، المكتب الإسلامي، بيروت، الطبعة الأولى ١٤٠٨؟ – ١٩٨٨م."],[606,"٨٧- غريب الحديث، لأبي إسحاق الحربي، إبراهيم بن إسحاق (ت٢٨٥؟)، تحقيق د. سليمان العايد، مطبوعات جامعة أم القرى، مكة المكرمة، الطبعة الأولى ١٤٠٥؟."],[607,"٨٨- الغيلانيات، لأبي بكر محمد بن عبد الله الشافعي البزاز (ت٣٥٤؟)، تحقيق د. حلمي كامل أسعد، دار ابن الجوزي، الدمام، الطبعة الأولى ١٤١٨؟."],[608,"٨٩- الفتاوى، لشيخ الإسلام ابن تيمية: أحمد بن عبد الحليم (ت٧٢٨؟)، جمع وترتيب عبد الرحمن بن قاسم، توزيع الرئاسة العامة للإفتاء، الرياض."],[609,"٩٠- فتح الباري، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق محب الدين الخطيب، المكتبة السلفية، القاهرة، الطبعة الثانية ١٤٠٠؟."],[610,"٩١- فتح المغيث، شرح ألفية الحديث، للسخاوي: محمد بن عبد الرحمن (ت٩٠٢؟)، تحقيق عبد الرحمن محمد عثمان، المكتبة السلفية، المدينة النبوية، الطبعة الثانية ١٣٨٨؟."],[611,"٩٢- الفصل للوصل المدرج في النقل، للخطيب البغدادي (ت٤٦٣؟)، تحقيق د. محمد مطر الزهراني، دار الهجرة للنشر والتوزيع، الثقبة، الطبعة الأولى ١٤١٨؟."],[612,"٩٣- الفوائد الحسان (مشيخة ابن النقور) لأبي بكرعبد الله بن محمد بن النقور (ت٥٦٥؟) تحقيق مسعد السعدني، مكتبة أضواء السلف، الرياض، الطبعة الأولى ١٤١٨؟."],[613,"٩٤- الفوائد المنتخبة (المهروانيات)، لأبي القاسم يوسف بن محمد المهرواني (ت٤٦٨؟) تخريج الخطيب البغدادي، تحقيق خليل العربي، مكتبة التوعية الإسلامية، مصر، الطبعة الأولى ١٤١٥؟."],[614,"٩٥- كتاب الكبائر، للذهبي: محمد بن أحمد (ت٧٤٨؟)، تحقيق محيي الدين مستو، دار ابن كثير، دمشق، الطبعة الثانية، ١٤٠٥؟."],[615,"٩٦- كشف الأستار عن زوائد البزار، للحافظ علي بن أبي بكر الهيثمي (ت٨٠٧؟)، تحقيق حبيب الرحمن الأعظمي، مؤسسة الرسالة، بيروت، الطبعة الأولى ١٤٠٥؟."],[616,"٩٧- الكفاية في علم الرواية، للخطيب البغدادي: أحمد بن علي (ت٤٦٢؟)، مصورة عن الطبعة الهندية، المكتبة العلمية، المدينة النبوية."],[617,"٩٨- لسان الميزان، للحافظ ابن حجر العسقلاني (ت٨٥٢؟) مصورة عن طبعة دائرة المعارف النظامية بالهند، تصويرمؤسسة الأعلمي، بيروت."],[618,"٩٩- مجمع البحرين في زوائد المعجمين، للحافظ الهيثمي (ت٨٠٧؟)، تحقيق عبد القدوس نذير، مكتبة الرشد، الرياض، الطبعة الأولى ١٤١٣؟."],[619,"١٠٠- مجمع الزوائد ومنبع الفوائد، للحافظ علي بن أبي بكر الهيثمي (ت٨٠٧؟)، دار الكتاب العربي، بيروت، الطبعة الثالثة ١٤٠٢؟ – ١٩٨٢م."],[620,"١٠١- المحدث الفاصل بين الراوي والواعي، للرامهرمزي: الحسن بن عبد الرحمن (ت٣٦٠؟)، تحقيق محمد عجاج الخطيب، دار الفكر، الطبعة الثالثة ١٤٠٤؟."],[621,"١٠٢- المحلى، لابن حزم الأندلسي: أبي محمد علي بن أحمد (ت٤٥٦؟)، تحقيق أحمد شاكر، دار الآفاق الجديدة، بيروت."],[622,"١٠٣- المدخل إلى السنن الكبرى، للإمام البيهقي (ت٤٥٨؟)، تحقيق د. محمد ضياء الرحمن الأعظمي، دار الخلفاء للكتاب الإسلامي، الكويت، لم تذكر سنة الطبع."],[623,"١٠٤- كتاب المراسيل، لابن أبي حاتم الرازي (ت٣٢٧؟)، تحقيق شكر الله قوجاني، مؤسسة الرسالة، بيروت، الطبعة الثانية ١٤٠٢؟ – ١٩٨٢م."],[624,"١٠٥- مسألة في التوحيد وفضل لا إله إلا الله، للإمام يوسف بن عبد الهادي (ت٩٠٩؟)، تحقيق عبد الهادي منصور، دار البشائر الإسلامية، الطبعة الأولى١٤١٦؟."],[625,"١٠٦- مسانيد أبي يحيى فراس بن يحيى المكتب (ت١٢٩؟)، جمع أبي نعيم الأصبهاني (٤٣٠؟)، تحقيق محمد المصري، مطابع ابن تيمية، القاهرة، الطبعة الأولى ١٤١٣؟."],[626,"١٠٧- مساوئ الأخلاق ومذمومها، للخرائطي، محمد بن جعفر السامري (ت٣٢٧؟)، تحقيق مجدي السيد، مكتبة القرآن، القاهرة، لم تذكر سنة الطبع."],[627,"١٠٨- المستخرج على صحيح مسلم، لأبي نعيم الأصبهاني (ت٤٣٠؟)، تحقيق محمد حسن الشافعي، دار الكتب العلمية، بيروت، الطبعة الأولى، ١٤١٧؟."],[628,"١٠٩- المستخرج على صحيح مسلم، لأبي عوانة، المطبوع باسم مسند أبي عوانة، مصورة عن الطبعة الهندية، تصوير دار الكتب، مصر."],[629,"١١٠- المستدرك على الصحيحين، للحاكم النيسابوري، محمد بن عبد الله (ت٤٠٥؟)، مصورة عن الطبعة الهندية، دار المعرفة، بيروت."],[630,"١١١- مسند الإمام أحمد، للإمام أحمد بن حنبل الشيباني (ت٢٤١؟)، تصوير دار الفكر العربي، بيروت."],[631,"١١٢- مسند الإمام أحمد، للإمام أحمد بن حنبل، تحقيق شعيب الأرناؤوط وآخرين، مؤسسة الرسالة، بيروت، الطبعة الأولى ١٤١٣؟."],[632,"١١٣- مسند إسحاق بن راهويه، للإمام إسحاق بن إبراهيم المروزي (ت٢٣٨؟)، تحقيق د. عبد الغفور البلوشي، مكتبة الإيمان، المدينة النبوية، الطبعة الأولى ١٤١٢؟."],[633,"١١٤- مسند أبي داود الطيالسي، للإمام سليمان بن داود (ت٢٠٤؟)، تصوير دار المعرفة، بيروت."],[634,"١١٥- مسند ابن أبي شيبة، لأبي بكر عبد الله بن محمد بن أبي شيبة (ت٢٣٥؟)، تحقيق عادل العزازي، أحمد المزيدي، دار الوطن، الرياض، الطبعة الأولى ١٤١٨؟."],[635,"*- مسند أبي عوانة، انظر المستخرج على صحيح مسلم."],[636,"١١٦- مسند أبي يعلى الموصلي، للإمام أحمد بن علي الموصلي (ت٣٠٧؟)، تحقيق حسين سليم أسد، دار المأمون، دمشق، الطبعة الأولى ١٤٠٤؟ – ١٩٨٤م."],[637,"١١٧- مسند الشاشي: الهيثم بن كليب (ت٣٣٥؟)، تحقيق د. محفوظ الرحمن زين الله، مكتبة العلوم والحكم، المدينة النبوية، الطبعة الأولى ١٤١٠؟."],[638,"١١٨- مسند الشاميين، لأبي القاسم سليمان بن أحمد الطبراني (ت٣٦٠؟)، تحقيق حمدي السلفي، مؤسسة الرسالة، بيروت، الطبعة الأولى١٤٠٩؟ – ١٩٨٩م."],[639,"*مشكل الآثار، انظر: شرح مشكل الآثار."],[640,"١١٩- مشيخة ابن الحطاب الرازي: محمد بن أحمد (ت٥٢٥؟)، بانتقاء أبي طاهر السلفي، تحقيق الشريف حاتم العوني، دار الهجرة، الثقبة، الطبعة الأولى١٤١٥؟."],[641,"١٢٠- المصنف، لأبي بكر عبد الله بن محمد بن أبي شيبة (ت٢٣٥؟)، تحقيق مختار الندوي، الدار السلفية، الهند، الطبعة الأولى ١٤٠١؟ – ١٩٨١م."],[642,"١٢١- المصنف، لعبد الرازق بن همام الصنعاني (ت٢١١؟)، تحقيق حبيب الرحمن الأعظمي، المكتب الإسلامي، بيروت، الطبعة الثانية ١٤٠٣؟-١٩٨٣م."],[643,"١٢٢- المطالب العالية بزوائد المسانيد الثمانية، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، (النسخة المسندة)، تحقيق غنيم عباس، ياسر إبراهيم، دار الوطن، الرياض، الطبعة الأولى ١٤١٨؟."],[644,"١٢٣- المعجم الأوسط، للإمام الطبراني، سليمان بن أحمد (ت٣٦٠؟)، تحقيق محمود الطحان، مكتبة المعارف، الرياض، الطبعة الأولى ١٤٠٥؟ – ١٩٨٥م."],[645,"١٢٤- معجم البلدان، لياقوت بن عبد الله الحموي (ت٦٢٦؟)، تحقيق فريد الجندي، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤١٠؟."],[646,"١٢٥- معجم الصحابة، لابن قانع: أبي الحسين عبد الباقي بن قانع (ت٣٥١؟)، تحقيق صلاح المصراتي، مكتبة الغرباء الأثرية، المدينة النبوية، الطبعة الأولى ١٤١٨؟."],[647,"١٢٦- المعجم الكبير، للحافظ الطبراني، سليمان بن أحمد (ت٣٦٠؟)، تحقيق حمدي السلفي، الطبعة الثانية."],[648,"١٢٧- معرفة الصحابة، لأبي نعيم الأصبهاني، أحمد بن عبد الله (ت٤٣٠؟)، تحقيق محمد راضي عثمان، مكتبة الدار بالمدينة ومكتبة الحرمين بالرياض، الطبعة الأولى ١٤٠٨؟."],[649,"١٢٨- معرفة علوم الحديث، للحاكم النيسابوري: محمد بن عبد الله (ت٤٠٥؟)، تحقيق معظم حسين، المكتبة العلمية، المدينة النبوية، الطبعة الثانية ١٣٩٧؟."],[650,"١٢٩- المعرفة والتاريخ، للفسوي، يعقوب بن سفيان (ت٢٧٧؟)، تحقيق د. أكرم العمري، مؤسسة الرسالة، بيروت، الطبعة الثانية ١٤٠١؟ – ١٩٨١م."],[651,"١٣٠- المغني في الضعفاء، للإمام الذهبي، محمد بن أحمد (ت٧٤٨؟)، تحقيق نور الدين عتر، إدارة إحياء التراث الإسلامي، قطر، الطبعة الثانية ١٤٠٧؟."],[652,"*المهروانيات: انظر الفوائد المنتخبة."],[653,"١٣١- موافقة الخُبْر الخَبَر في تخريج أحاديث المختصر، للحافظ ابن حجر العسقلاني (ت٨٥٢؟)، تحقيق حمدي السلفي، صبحي السامرائي، مكتبة الرشد، الرياض الطبعة الأولى ١٤١٢؟."],[654,"١٣٢- الموطأ، للإمام مالك بن أنس (ت١٧٩؟)، رواية يحيى بن يحيى الليثي (ت٢٣٤؟)، تحقيق محمد فؤاد عبد الباقي، دار إحياء الكاتب العربي، مصر."],[655,"١٣٣- ميزان الاعتدال في نقد الرجال، للإمام الذهبي، محمد بن أحمد (ت٧٤٨؟)، تحقيق علي محمد البجاوي، دار المعرفة، بيروت."],[656,"١٣٤- الوسيط في تفسير القرآن المجيد، لأبي الحسن علي بن أحمد الواحدي (ت٤٦٨؟)، تحقيق عادل عبد الموجود وآخرين، دار الكتب العلمية، بيروت، الطبعة الأولى ١٤١٥؟."]])